export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-2d-data-on-3d-plot":{"intro":"This lab demonstrates how to plot 2D data on selective axes of a 3D plot using ax.plot's zdir keyword. The matplotlib library in Python is used to create the 3D plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. We need matplotlib and numpy to plot the 3D graph."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a 3D Plot","body":["The second step is to create a 3D plot using ax = plt.figure().add_subplot(projection='3d')."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')"}]},{"title":"Plot 2D Data on the 3D Plot","body":["The third step is to plot 2D data on the 3D plot using ax.plot and ax.scatter. The ax.plot function plots a sin curve using the x and y axes. The ax.scatter function plots scatterplot data on the x and z axes."],"code":[{"lang":"python","text":"# Plot a sin curve using the x and y axes.\nx = np.linspace(0, 1, 100)\ny = np.sin(x * 2 * np.pi) / 2 + 0.5\nax.plot(x, y, zs=0, zdir='z', label='curve in (x, y)')\n\n# Plot scatterplot data (20 2D points per colour) on the x and z axes.\ncolors = ('r', 'g', 'b', 'k')\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nx = np.random.sample(20 * len(colors))\ny = np.random.sample(20 * len(colors))\nc_list = []\nfor c in colors:\n    c_list.extend([c] * 20)\n# By using zdir='y', the y value of these points is fixed to the zs value 0\n# and the (x, y) points are plotted on the x and z axes.\nax.scatter(x, y, zs=0, zdir='y', c=c_list, label='points in (x, z)')"}]},{"title":"Customize the Plot","body":["The fourth step is to customize the plot by adding a legend, setting axes limits and labels, and changing the view angle."],"code":[{"lang":"python","text":"# Make legend, set axes limits and labels\nax.legend()\nax.set_xlim(0, 1)\nax.set_ylim(0, 1)\nax.set_zlim(0, 1)\nax.set_xlabel('X')\nax.set_ylabel('Y')\nax.set_zlabel('Z')\n\n# Customize the view angle so it's easier to see that the scatter points lie\n# on the plane y=0\nax.view_init(elev=20., azim=-35, roll=0)\n\nplt.show()"}]},{"title":"View the Plot","body":["The final step is to view the 3D plot by running the code."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-3d-bar-chart":{"intro":"In this lab, we will learn how to create a 3D bar chart using Python Matplotlib. We will use fake data to plot the chart with and without shading.","steps":[{"title":"Import Libraries and Set Up Figure","body":["Import Libraries and Set Up Figure","In the first step, we will import the necessary libraries and set up the figure and axes for the chart."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# set up the figure and axes\nfig = plt.figure(figsize=(8, 3))\nax1 = fig.add_subplot(121, projection='3d')\nax2 = fig.add_subplot(122, projection='3d')"}]},{"title":"Create Fake Data","body":["In the second step, we will create fake data to use for the chart."],"code":[{"lang":"python","text":"# fake data\n_x = np.arange(4)\n_y = np.arange(5)\n_xx, _yy = np.meshgrid(_x, _y)\nx, y = _xx.ravel(), _yy.ravel()\n\ntop = x + y\nbottom = np.zeros_like(top)\nwidth = depth = 1"}]},{"title":"Plot the Chart with Shading","body":["In the third step, we will plot the 3D bar chart with shading."],"code":[{"lang":"python","text":"ax1.bar3d(x, y, bottom, width, depth, top, shade=True)\nax1.set_title('Shaded')"}]},{"title":"Plot the Chart without Shading","body":["Plot the Chart without Shading","In the fourth step, we will plot the 3D bar chart without shading."],"code":[{"lang":"python","text":"ax2.bar3d(x, y, bottom, width, depth, top, shade=False)\nax2.set_title('Not Shaded')"}]},{"title":"Display the Chart","body":["In the final step, we will display the chart."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-accented-text-visualization":{"intro":"Matplotlib is a library in Python used for data visualization. It supports accented characters via TeX mathtext or Unicode. This tutorial will demonstrate how to use accented text in Matplotlib.","steps":[{"title":"Using Mathtext","body":["Mathtext is a feature in Matplotlib that allows you to use TeX commands to render mathematical symbols and equations. Mathtext also supports accented characters."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Mathtext demo\nfig, ax = plt.subplots()\nax.plot(range(10))\nax.set_title(r'$\\ddot{o}\\acute{e}\\grave{e}\\hat{O}'\n             r'\\breve{i}\\bar{A}\\tilde{n}\\vec{q}$', fontsize=20)\n\n# Shorthand is also supported and curly braces are optional\nax.set_xlabel(r\"\"\"$\\\"o\\ddot o \\'e\\`e\\~n\\.x\\^y$\"\"\", fontsize=20)\nax.text(4, 0.5, r\"$F=m\\ddot{x}$\")\nfig.tight_layout()"}]},{"title":"Using Unicode Characters","body":["Matplotlib also supports the use of Unicode characters directly in strings."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\n# Unicode demo\nfig, ax = plt.subplots()\nax.set_title(\"GISCARD CHAHUTÉ À L'ASSEMBLÉE\")\nax.set_xlabel(\"LE COUP DE DÉ DE DE GAULLE\")\nax.set_ylabel('André was here!')\nax.text(0.2, 0.8, 'Institut für Festkörperphysik', rotation=45)\nax.text(0.4, 0.2, 'AVA (check kerning)')\n\nplt.show()"}]},{"title":"Running the Code","body":["To run the code, you must have Matplotlib installed. You can install Matplotlib using pip. Open the command prompt and type:"],"code":[{"lang":"python","text":"pip install matplotlib"}]}],"commands":[],"reference":[{"path":"reference.py","text":"pip install matplotlib"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-shaded-plot-visualization":{"intro":"This lab will walk you through the process of creating shaded plots in Matplotlib using different techniques. You will learn how to display a colorbar for a shaded plot, avoid outliers in a shaded plot, and display different variables through shade and color.","steps":[{"title":"Displaying a Colorbar for a Shaded Plot","body":["Displaying a Colorbar for a Shaded Plot","In this step, you will learn how to display a correct numeric colorbar for a shaded plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.colors import LightSource, Normalize\n\ndef display_colorbar():\n    \"\"\"Display a correct numeric colorbar for a shaded plot.\"\"\"\n    y, x = np.mgrid[-4:2:200j, -4:2:200j]\n    z = 10 * np.cos(x**2 + y**2)\n\n    cmap = plt.cm.copper\n    ls = LightSource(315, 45)\n    rgb = ls.shade(z, cmap)\n\n    fig, ax = plt.subplots()\n    ax.imshow(rgb, interpolation='bilinear')\n\n    # Use a proxy artist for the colorbar...\n    im = ax.imshow(z, cmap=cmap)\n    im.remove()\n    fig.colorbar(im, ax=ax)\n\n    ax.set_title('Using a colorbar with a shaded plot', size='x-large')"}]},{"title":"Avoiding Outliers in Shaded Plots","body":["Avoiding Outliers in Shaded Plots","In this step, you will learn how to use a custom norm to control the displayed z-range of a shaded plot."],"code":[{"lang":"python","text":"def avoid_outliers():\n    \"\"\"Use a custom norm to control the displayed z-range of a shaded plot.\"\"\"\n    y, x = np.mgrid[-4:2:200j, -4:2:200j]\n    z = 10 * np.cos(x**2 + y**2)\n\n    # Add some outliers...\n    z[100, 105] = 2000\n    z[120, 110] = -9000\n\n    ls = LightSource(315, 45)\n    fig, (ax1, ax2) = plt.subplots(ncols=2, figsize=(8, 4.5))\n\n    rgb = ls.shade(z, plt.cm.copper)\n    ax1.imshow(rgb, interpolation='bilinear')\n    ax1.set_title('Full range of data')\n\n    rgb = ls.shade(z, plt.cm.copper, vmin=-10, vmax=10)\n    ax2.imshow(rgb, interpolation='bilinear')\n    ax2.set_title('Manually set range')\n\n    fig.suptitle('Avoiding Outliers in Shaded Plots', size='x-large')"}]},{"title":"Displaying Different Variables Through Shade and Color","body":["Displaying Different Variables Through Shade and Color","In this step, you will learn how to display different variables through shade and color."],"code":[{"lang":"python","text":"def shade_other_data():\n    \"\"\"Demonstrates displaying different variables through shade and color.\"\"\"\n    y, x = np.mgrid[-4:2:200j, -4:2:200j]\n    z1 = np.sin(x**2)  # Data to hillshade\n    z2 = np.cos(x**2 + y**2)  # Data to color\n\n    norm = Normalize(z2.min(), z2.max())\n    cmap = plt.cm.RdBu\n\n    ls = LightSource(315, 45)\n    rgb = ls.shade_rgb(cmap(norm(z2)), z1)\n\n    fig, ax = plt.subplots()\n    ax.imshow(rgb, interpolation='bilinear')\n    ax.set_title('Shade by one variable, color by another', size='x-large')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def shade_other_data():\n    \"\"\"Demonstrates displaying different variables through shade and color.\"\"\"\n    y, x = np.mgrid[-4:2:200j, -4:2:200j]\n    z1 = np.sin(x**2)  # Data to hillshade\n    z2 = np.cos(x**2 + y**2)  # Data to color\n\n    norm = Normalize(z2.min(), z2.max())\n    cmap = plt.cm.RdBu\n\n    ls = LightSource(315, 45)\n    rgb = ls.shade_rgb(cmap(norm(z2)), z1)\n\n    fig, ax = plt.subplots()\n    ax.imshow(rgb, interpolation='bilinear')\n    ax.set_title('Shade by one variable, color by another', size='x-large')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-affine-transformation":{"intro":"This lab demonstrates how to use Matplotlib to perform affine transformation of an image. Affine transformations change the shape and orientation of an image. This lab shows how to use the transforms.Affine2D function to manipulate the shape and orientation of an image.","steps":[{"title":"Import Libraries and Define the Image","body":["Import Libraries and Define the Image","In the first step, we import the necessary libraries and define the image that will be used in the example. The image is a combination of two Gaussian functions."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.transforms as mtransforms\n\ndef get_image():\n    delta = 0.25\n    x = y = np.arange(-3.0, 3.0, delta)\n    X, Y = np.meshgrid(x, y)\n    Z1 = np.exp(-X**2 - Y**2)\n    Z2 = np.exp(-(X - 1)**2 - (Y - 1)**2)\n    Z = (Z1 - Z2)\n    return Z"}]},{"title":"Create a Function to Plot the Image","body":["Create a Function to Plot the Image","In this step, we define a function that takes the image, the plot axis, and the transformation as inputs. The function displays the image on the plot axis with the specified transformation. The function also displays a yellow rectangle around the image to show the intended extent of the image."],"code":[{"lang":"python","text":"def do_plot(ax, Z, transform):\n    im = ax.imshow(Z, interpolation='none',\n                   origin='lower',\n                   extent=[-2, 4, -3, 2], clip_on=True)\n\n    trans_data = transform + ax.transData\n    im.set_transform(trans_data)\n\n    # display intended extent of the image\n    x1, x2, y1, y2 = im.get_extent()\n    ax.plot([x1, x2, x2, x1, x1], [y1, y1, y2, y2, y1], \"y--\",\n            transform=trans_data)\n    ax.set_xlim(-5, 5)\n    ax.set_ylim(-4, 4)"}]},{"title":"Perform Image Rotation","body":["In this step, we perform a rotation of the image using the rotate_deg function. We pass the rotation angle as the input to the rotate_deg function. We use the do_plot function to display the rotated image."],"code":[{"lang":"python","text":"# prepare image and figure\nfig, ax1 = plt.subplots()\nZ = get_image()\n\n# image rotation\ndo_plot(ax1, Z, mtransforms.Affine2D().rotate_deg(30))"}]},{"title":"Perform Image Skew","body":["In this step, we perform a skew of the image using the skew_deg function. We pass the skew angles as inputs to the skew_deg function. We use the do_plot function to display the skewed image."],"code":[{"lang":"python","text":"# prepare image and figure\nfig, ax2 = plt.subplots()\nZ = get_image()\n\n# image skew\ndo_plot(ax2, Z, mtransforms.Affine2D().skew_deg(30, 15))"}]},{"title":"Perform Image Scale and Reflection","body":["Perform Image Scale and Reflection","In this step, we perform a scale and reflection of the image using the scale function. We pass the scale and reflection factors as inputs to the scale function. We use the do_plot function to display the scaled and reflected image."],"code":[{"lang":"python","text":"# prepare image and figure\nfig, ax3 = plt.subplots()\nZ = get_image()\n\n# scale and reflection\ndo_plot(ax3, Z, mtransforms.Affine2D().scale(-1, .5))"}]},{"title":"Perform Multiple Transformations","body":["Perform Multiple Transformations","In this step, we perform multiple transformations of the image using the rotate_deg, skew_deg, scale, and translate functions. We pass the transformation parameters as inputs to the respective functions. We use the do_plot function to display the transformed image."],"code":[{"lang":"python","text":"# prepare image and figure\nfig, ax4 = plt.subplots()\nZ = get_image()\n\n# everything and a translation\ndo_plot(ax4, Z, mtransforms.Affine2D().\n        rotate_deg(30).skew_deg(30, 15).scale(-1, .5).translate(.5, -1))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# prepare image and figure\nfig, ax4 = plt.subplots()\nZ = get_image()\n\n# everything and a translation\ndo_plot(ax4, Z, mtransforms.Affine2D().\n        rotate_deg(30).skew_deg(30, 15).scale(-1, .5).translate(.5, -1))"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-align-matplotlib-axis-labels":{"intro":"In data visualization, it is important to have clear and properly aligned labels for the x and y axes. Matplotlib provides several functions to help align these labels properly. In this lab, we will use the align_xlabels and align_ylabels functions to align the labels in our plot.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries for our plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.gridspec as gridspec"}]},{"title":"Create the Plot","body":["Next, we will create the plot with properly labeled axes."],"code":[{"lang":"python","text":"fig = plt.figure(tight_layout=True)\ngs = gridspec.GridSpec(2, 2)\n\nax = fig.add_subplot(gs[0, :])\nax.plot(np.arange(0, 1e6, 1000))\nax.set_ylabel('YLabel0')\nax.set_xlabel('XLabel0')\n\nfor i in range(2):\n    ax = fig.add_subplot(gs[1, i])\n    ax.plot(np.arange(1., 0., -0.1) * 2000., np.arange(1., 0., -0.1))\n    ax.set_ylabel('YLabel1 %d' % i)\n    ax.set_xlabel('XLabel1 %d' % i)\n    if i == 0:\n        ax.tick_params(axis='x', rotation=55)"}]},{"title":"Align Labels","body":["We will now use the align_xlabels and align_ylabels functions to align the labels properly. Alternatively, we can use the align_labels function to do both at once."],"code":[{"lang":"python","text":"fig.align_labels()  # same as fig.align_xlabels(); fig.align_ylabels()"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-align-y-labels-in-matplotlib-plots":{"intro":"In this lab, you will learn how to align y-labels in Matplotlib plots. The alignment of y-labels is important for improving the readability of plots, especially when there are multiple subplots.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. In this lab, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create the Plot","body":["The next step is to create the plot. We will create a plot with two subplots, where the y-labels are not aligned."],"code":[{"lang":"python","text":"def make_plot(axs):\n    box = dict(facecolor='yellow', pad=5, alpha=0.2)\n\n    # Fixing random state for reproducibility\n    np.random.seed(19680801)\n    ax1 = axs[0, 0]\n    ax1.plot(2000*np.random.rand(10))\n    ax1.set_title('ylabels not aligned')\n    ax1.set_ylabel('misaligned 1', bbox=box)\n    ax1.set_ylim(0, 2000)\n\n    ax3 = axs[1, 0]\n    ax3.set_ylabel('misaligned 2', bbox=box)\n    ax3.plot(np.random.rand(10))\n\n    ax2 = axs[0, 1]\n    ax2.set_title('ylabels aligned')\n    ax2.plot(2000*np.random.rand(10))\n    ax2.set_ylabel('aligned 1', bbox=box)\n    ax2.set_ylim(0, 2000)\n\n    ax4 = axs[1, 1]\n    ax4.plot(np.random.rand(10))\n    ax4.set_ylabel('aligned 2', bbox=box)\n\nfig, axs = plt.subplots(2, 2)\nfig.subplots_adjust(left=0.2, wspace=0.6)\nmake_plot(axs)\nplt.show()"}]},{"title":"Align Y-Labels Automatically","body":["The third step is to align the y-labels automatically using the .Figure.align_ylabels method."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2)\nfig.subplots_adjust(left=0.2, wspace=0.6)\nmake_plot(axs)\nfig.align_ylabels(axs[:, 1])\nplt.show()"}]},{"title":"Align Y-Labels Manually","body":["The fourth step is to align the y-labels manually using the ~.Axis.set_label_coords method of the y-axis object."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2)\nfig.subplots_adjust(left=0.2, wspace=0.6)\nmake_plot(axs)\n\nlabex = -0.3  # axes coords\n\nfor j in range(2):\n    axs[j, 1].yaxis.set_label_coords(labex, 0.5)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axs = plt.subplots(2, 2)\nfig.subplots_adjust(left=0.2, wspace=0.6)\nmake_plot(axs)\n\nlabex = -0.3  # axes coords\n\nfor j in range(2):\n    axs[j, 1].yaxis.set_label_coords(labex, 0.5)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-fundamentals":{"intro":"In this lab, you will learn how to use Matplotlib, a Python library for creating visualizations, to create a figure and annotate its anatomy. You will learn how to create a figure, plot data, set axis limits, add labels and titles, and annotate the figure with text and markers.","steps":[{"title":"Import libraries and set up data","body":["Import libraries and set up data","First, we need to import the necessary libraries and set up some data to plot. In this example, we will plot three sine waves with some random noise added to them."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Set up data\nnp.random.seed(19680801)\n\nX = np.linspace(0.5, 3.5, 100)\nY1 = 3+np.cos(X)\nY2 = 1+np.cos(1+X/0.75)/2\nY3 = np.random.uniform(Y1, Y2, len(X))"}]},{"title":"Create the figure and set up the axes","body":["Create the figure and set up the axes","Next, we will create a figure and set up the axes. We will use the add_axes() method to create a new set of axes within the figure. We will also set limits for the x and y axes and add gridlines."],"code":[{"lang":"python","text":"# Create figure and axes\nfig = plt.figure(figsize=(7.5, 7.5))\nax = fig.add_axes([0.2, 0.17, 0.68, 0.7], aspect=1)\n\n# Set limits and gridlines\nax.set_xlim(0, 4)\nax.set_ylim(0, 4)\nax.grid(linestyle=\"--\", linewidth=0.5, color='.25', zorder=-10)"}]},{"title":"Plot the data","body":["Now we will plot our data on the axes we just created. We will use the plot() method to plot the three sine waves with different colors and line widths."],"code":[{"lang":"python","text":"# Plot data\nax.plot(X, Y1, c='C0', lw=2.5, label=\"Blue signal\", zorder=10)\nax.plot(X, Y2, c='C1', lw=2.5, label=\"Orange signal\")\nax.plot(X[::3], Y3[::3], linewidth=0, markersize=9,\n        marker='s', markerfacecolor='none', markeredgecolor='C4',\n        markeredgewidth=2.5)"}]},{"title":"Add labels and title","body":["We will now add labels to the x and y axes, and a title to the figure using the set_xlabel(), set_ylabel(), and set_title() methods."],"code":[{"lang":"python","text":"# Add labels and title\nax.set_xlabel(\"x Axis label\", fontsize=14)\nax.set_ylabel(\"y Axis label\", fontsize=14)\nax.set_title(\"Anatomy of a figure\", fontsize=20, verticalalignment='bottom')"}]},{"title":"Add legend","body":["We will add a legend to the figure using the legend() method. We will also specify the location and font size of the legend."],"code":[{"lang":"python","text":"# Add legend\nax.legend(loc=\"upper right\", fontsize=14)"}]},{"title":"Annotate the figure","body":["Finally, we will annotate the figure to show the names of various Matplotlib elements using the text() and Circle() methods. We will also use the withStroke() method to add a white outline to the text and markers for better visibility."],"code":[{"lang":"python","text":"# Annotate the figure\nfrom matplotlib.patches import Circle\nfrom matplotlib.patheffects import withStroke\n\nroyal_blue = [0, 20/256, 82/256]\n\ndef annotate(x, y, text, code):\n    # Circle marker\n    c = Circle((x, y), radius=0.15, clip_on=False, zorder=10, linewidth=2.5,\n               edgecolor=royal_blue + [0.6], facecolor='none',\n               path_effects=[withStroke(linewidth=7, foreground='white')])\n    ax.add_artist(c)\n\n    # use path_effects as a background for the texts\n    # draw the path_effects and the colored text separately so that the\n    # path_effects cannot clip other texts\n    for path_effects in [[withStroke(linewidth=7, foreground='white')], []]:\n        color = 'white' if path_effects else royal_blue\n        ax.text(x, y-0.2, text, zorder=100,\n                ha='center', va='top', weight='bold', color=color,\n                style='italic', fontfamily='Courier New',\n                path_effects=path_effects)\n\n        color = 'white' if path_effects else 'black'\n        ax.text(x, y-0.33, code, zorder=100,\n                ha='center', va='top', weight='normal', color=color,\n                fontfamily='monospace', fontsize='medium',\n                path_effects=path_effects)\n\nannotate(3.5, -0.13, \"Minor tick label\", \"ax.xaxis.set_minor_formatter\")\nannotate(-0.03, 1.0, \"Major tick\", \"ax.yaxis.set_major_locator\")\nannotate(0.00, 3.75, \"Minor tick\", \"ax.yaxis.set_minor_locator\")\nannotate(-0.15, 3.00, \"Major tick label\", \"ax.yaxis.set_major_formatter\")\nannotate(1.68, -0.39, \"xlabel\", \"ax.set_xlabel\")\nannotate(-0.38, 1.67, \"ylabel\", \"ax.set_ylabel\")\nannotate(1.52, 4.15, \"Title\", \"ax.set_title\")\nannotate(1.75, 2.80, \"Line\", \"ax.plot\")\nannotate(2.25, 1.54, \"Markers\", \"ax.scatter\")\nannotate(3.00, 3.00, \"Grid\", \"ax.grid\")\nannotate(3.60, 3.58, \"Legend\", \"ax.legend\")\nannotate(2.5, 0.55, \"Axes\", \"fig.subplots\")\nannotate(4, 4.5, \"Figure\", \"plt.figure\")\nannotate(0.65, 0.01, \"x Axis\", \"ax.xaxis\")\nannotate(0, 0.36, \"y Axis\", \"ax.yaxis\")\nannotate(4.0, 0.7, \"Spine\", \"ax.spines\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Annotate the figure\nfrom matplotlib.patches import Circle\nfrom matplotlib.patheffects import withStroke\n\nroyal_blue = [0, 20/256, 82/256]\n\ndef annotate(x, y, text, code):\n    # Circle marker\n    c = Circle((x, y), radius=0.15, clip_on=False, zorder=10, linewidth=2.5,\n               edgecolor=royal_blue + [0.6], facecolor='none',\n               path_effects=[withStroke(linewidth=7, foreground='white')])\n    ax.add_artist(c)\n\n    # use path_effects as a background for the texts\n    # draw the path_effects and the colored text separately so that the\n    # path_effects cannot clip other texts\n    for path_effects in [[withStroke(linewidth=7, foreground='white')], []]:\n        color = 'white' if path_effects else royal_blue\n        ax.text(x, y-0.2, text, zorder=100,\n                ha='center', va='top', weight='bold', color=color,\n                style='italic', fontfamily='Courier New',\n                path_effects=path_effects)\n\n        color = 'white' if path_effects else 'black'\n        ax.text(x, y-0.33, code, zorder=100,\n                ha='center', va='top', weight='normal', color=color,\n                fontfamily='monospace', fontsize='medium',\n                path_effects=path_effects)\n\nannotate(3.5, -0.13, \"Minor tick label\", \"ax.xaxis.set_minor_formatter\")\nannotate(-0.03, 1.0, \"Major tick\", \"ax.yaxis.set_major_locator\")\nannotate(0.00, 3.75, \"Minor tick\", \"ax.yaxis.set_minor_locator\")\nannotate(-0.15, 3.00, \"Major tick label\", \"ax.yaxis.set_major_formatter\")\nannotate(1.68, -0.39, \"xlabel\", \"ax.set_xlabel\")\nannotate(-0.38, 1.67, \"ylabel\", \"ax.set_ylabel\")\nannotate(1.52, 4.15, \"Title\", \"ax.set_title\")\nannotate(1.75, 2.80, \"Line\", \"ax.plot\")\nannotate(2.25, 1.54, \"Markers\", \"ax.scatter\")\nannotate(3.00, 3.00, \"Grid\", \"ax.grid\")\nannotate(3.60, 3.58, \"Legend\", \"ax.legend\")\nannotate(2.5, 0.55, \"Axes\", \"fig.subplots\")\nannotate(4, 4.5, \"Figure\", \"plt.figure\")\nannotate(0.65, 0.01, \"x Axis\", \"ax.xaxis\")\nannotate(0, 0.36, \"y Axis\", \"ax.yaxis\")\nannotate(4.0, 0.7, \"Spine\", \"ax.spines\")"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-anchored-objects":{"intro":"In this lab, you will learn how to use Anchored Objects in Matplotlib. Anchored Objects are used to add auxiliary objects to a plot. These objects can be used to add annotations, scale bars, and legends to a plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the required libraries. We will be using Matplotlib for this lab."],"code":[{"lang":"python","text":"from matplotlib import pyplot as plt\nfrom matplotlib.lines import Line2D\nfrom matplotlib.offsetbox import (AnchoredOffsetbox, AuxTransformBox,\n                                  DrawingArea, TextArea, VPacker)\nfrom matplotlib.patches import Circle, Ellipse"}]},{"title":"Create a Figure","body":["The next step is to create a figure. We will create a simple figure with a single subplot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_aspect(1)"}]},{"title":"Add Anchored Text","body":["In this step, we will add a text box anchored to the upper-left corner of the figure."],"code":[{"lang":"python","text":"def draw_text(ax):\n    \"\"\"Draw a text-box anchored to the upper-left corner of the figure.\"\"\"\n    box = AnchoredOffsetbox(child=TextArea(\"Figure 1a\"),\n                            loc=\"upper left\", frameon=True)\n    box.patch.set_boxstyle(\"round,pad=0.,rounding_size=0.2\")\n    ax.add_artist(box)\n\ndraw_text(ax)"}]},{"title":"Add Anchored Circles","body":["In this step, we will add two circles to the plot using Anchored Objects."],"code":[{"lang":"python","text":"def draw_circles(ax):\n    \"\"\"Draw circles in axes coordinates.\"\"\"\n    area = DrawingArea(width=40, height=20)\n    area.add_artist(Circle((10, 10), 10, fc=\"tab:blue\"))\n    area.add_artist(Circle((30, 10), 5, fc=\"tab:red\"))\n    box = AnchoredOffsetbox(\n        child=area, loc=\"upper right\", pad=0, frameon=False)\n    ax.add_artist(box)\n\ndraw_circles(ax)"}]},{"title":"Add Anchored Ellipse","body":["In this step, we will add an ellipse to the plot using Anchored Objects."],"code":[{"lang":"python","text":"def draw_ellipse(ax):\n    \"\"\"Draw an ellipse of width=0.1, height=0.15 in data coordinates.\"\"\"\n    aux_tr_box = AuxTransformBox(ax.transData)\n    aux_tr_box.add_artist(Ellipse((0, 0), width=0.1, height=0.15))\n    box = AnchoredOffsetbox(child=aux_tr_box, loc=\"lower left\", frameon=True)\n    ax.add_artist(box)\n\ndraw_ellipse(ax)"}]},{"title":"Add Size Bar","body":["In this step, we will add a size bar to the plot using Anchored Objects."],"code":[{"lang":"python","text":"def draw_sizebar(ax):\n    \"\"\"\n    Draw a horizontal bar with length of 0.1 in data coordinates,\n    with a fixed label center-aligned underneath.\n    \"\"\"\n    size = 0.1\n    text = r\"1$^{\\prime}$\"\n    sizebar = AuxTransformBox(ax.transData)\n    sizebar.add_artist(Line2D([0, size], [0, 0], color=\"black\"))\n    text = TextArea(text)\n    packer = VPacker(\n        children=[sizebar, text], align=\"center\", sep=5)  # separation in points.\n    ax.add_artist(AnchoredOffsetbox(\n        child=packer, loc=\"lower center\", frameon=False,\n        pad=0.1, borderpad=0.5))  # paddings relative to the legend fontsize.\n\ndraw_sizebar(ax)"}]},{"title":"Display the Plot","body":["The final step is to display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-a-scale-invariant-angleel":{"intro":"In this tutorial, you will learn how to create a scale invariant angle label using Matplotlib. Angle annotation is often used to mark angles between lines or inside shapes with a circular arc. While Matplotlib provides an ~.patches.Arc, an inherent problem when directly using it for such purposes is that an arc being circular in data space is not necessarily circular in display space. Also, the arc's radius is often best defined in a coordinate system which is independent of the actual data coordinates - at least if you want to be able to freely zoom into your plot without the annotation growing to infinity. This calls for a solution where the arc's center is defined in data space, but its radius in a physical unit like points or pixels, or as a ratio of the Axes dimension.","steps":[{"title":"Import Required Libraries","body":[],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.patches import Arc\nfrom matplotlib.transforms import Bbox, IdentityTransform, TransformedBbox"}]},{"title":"Define AngleAnnotation Class","body":[],"code":[{"lang":"python","text":"class AngleAnnotation(Arc):\n    \"\"\"\n    Draws an arc between two vectors which appears circular in display space.\n    \"\"\"\n    def __init__(self, xy, p1, p2, size=75, unit=\"points\", ax=None,\n                 text=\"\", textposition=\"inside\", text_kw=None, **kwargs):\n        \"\"\"\n        Parameters\n        ----------\n        xy, p1, p2 : tuple or array of two floats\n            Center position and two points. Angle annotation is drawn between\n            the two vectors connecting *p1* and *p2* with *xy*, respectively.\n            Units are data coordinates.\n\n        size : float\n            Diameter of the angle annotation in units specified by *unit*.\n\n        unit : str\n            One of the following strings to specify the unit of *size*:\n\n            * \"pixels\": pixels\n            * \"points\": points, use points instead of pixels to not have a\n              dependence on the DPI\n            * \"axes width\", \"axes height\": relative units of Axes width, height\n            * \"axes min\", \"axes max\": minimum or maximum of relative Axes\n              width, height\n\n        ax : `matplotlib.axes.Axes`\n            The Axes to add the angle annotation to.\n\n        text : str\n            The text to mark the angle with.\n\n        textposition : {\"inside\", \"outside\", \"edge\"}\n            Whether to show the text in- or outside the arc. \"edge\" can be used\n            for custom positions anchored at the arc's edge.\n\n        text_kw : dict\n            Dictionary of arguments passed to the Annotation.\n\n        **kwargs\n            Further parameters are passed to `matplotlib.patches.Arc`. Use this\n            to specify, color, linewidth etc. of the arc.\n\n        \"\"\"\n        self.ax = ax or plt.gca()\n        self._xydata = xy  # in data coordinates\n        self.vec1 = p1"}]},{"title":"Define Helper Function plot_angle","body":["Define Helper Function plot_angle"],"code":[{"lang":"python","text":"def plot_angle(ax, pos, angle, length=0.95, acol=\"C0\", **kwargs):\n    vec2 = np.array([np.cos(np.deg2rad(angle)), np.sin(np.deg2rad(angle))])\n    xy = np.c_[[length, 0], [0, 0], vec2*length].T + np.array(pos)\n    ax.plot(*xy.T, color=acol)\n    return AngleAnnotation(pos, xy[0], xy[2], ax=ax, **kwargs)"}]},{"title":"Plot Two Crossing Lines and Label Each Angle Between Them with the Above AngleAnnotation Tool","body":["Plot Two Crossing Lines and Label Each Angle Between Them with the Above AngleAnnotation Tool."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfig.canvas.draw()  # Need to draw the figure to define renderer\nax.set_title(\"AngleLabel example\")\n\n# Plot two crossing lines and label each angle between them with the above\n# ``AngleAnnotation`` tool.\ncenter = (4.5, 650)\np1 = [(2.5, 710), (6.0, 605)]\np2 = [(3.0, 275), (5.5, 900)]\nline1, = ax.plot(*zip(*p1))\nline2, = ax.plot(*zip(*p2))\npoint, = ax.plot(*center, marker=\"o\")\n\nam1 = AngleAnnotation(center, p1[1], p2[1], ax=ax, size=75, text=r\"$\\alpha$\")\nam2 = AngleAnnotation(center, p2[1], p1[0], ax=ax, size=35, text=r\"$\\beta$\")\nam3 = AngleAnnotation(center, p1[0], p2[0], ax=ax, size=75, text=r\"$\\gamma$\")\nam4 = AngleAnnotation(center, p2[0], p1[1], ax=ax, size=35, text=r\"$\\theta$\")\n\n\n# Showcase some styling options for the angle arc, as well as the text.\np = [(6.0, 400), (5.3, 410), (5.6, 300)]\nax.plot(*zip(*p))\nam5 = AngleAnnotation(p[1], p[0], p[2], ax=ax, size=40, text=r\"$\\Phi$\",\n                      linestyle=\"--\", color=\"gray\", textposition=\"outside\",\n                      text_kw=dict(fontsize=16, color=\"gray\"))\n\nplt.show()"}]},{"title":"Showcase Different Text Positions and Size Units","body":["Showcase Different Text Positions and Size Units"],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(nrows=2, sharex=True)\nfig.suptitle(\"AngleLabel keyword arguments\")\nfig.canvas.draw()  # Need to draw the figure to define renderer\n\n# Showcase different text positions.\nax1.margins(y=0.4)\nax1.set_title(\"textposition\")\nkw = dict(size=75, unit=\"points\", text=r\"$60°$\")\n\nam6 = plot_angle(ax1, (2.0, 0), 60, textposition=\"inside\", **kw)\nam7 = plot_angle(ax1, (3.5, 0), 60, textposition=\"outside\", **kw)\nam8 = plot_angle(ax1, (5.0, 0), 60, textposition=\"edge\",\n                 text_kw=dict(bbox=dict(boxstyle=\"round\", fc=\"w\")), **kw)\nam9 = plot_angle(ax1, (6.5, 0), 60, textposition=\"edge\",\n                 text_kw=dict(xytext=(30, 20), arrowprops=dict(arrowstyle=\"->\",\n                              connectionstyle=\"arc3,rad=-0.2\")), **kw)\n\nfor x, text in zip([2.0, 3.5, 5.0, 6.5], ['\"inside\"', '\"outside\"', '\"edge\"',\n                                          '\"edge\", custom arrow']):\n    ax1.annotate(text, xy=(x, 0), xycoords=ax1.get_xaxis_transform(),\n                 bbox=dict(boxstyle=\"round\", fc=\"w\"), ha=\"left\", fontsize=8,\n                 annotation_clip=True)\n\n# Showcase different size units. The effect of this can best be observed\n# by interactively changing the figure size\nax2.margins(y=0.4)\nax2.set_title(\"unit\")\nkw = dict(text=r\"$60°$\", textposition=\"outside\")\n\nam10 = plot_angle(ax2, (2.0, 0), 60, size=50, unit=\"pixels\", **kw)\nam11 = plot_angle(ax2, (3.5, 0), 60, size=50, unit=\"points\", **kw)\nam12 = plot_angle(ax2, (5.0, 0), 60, size=0.25, unit=\"axes min\", **kw)\nam13 = plot_angle(ax2, (6.5, 0), 60, size=0.25, unit=\"axes max\", **kw)\n\nfor x, text in zip([2.0, 3.5, 5.0, 6.5], ['\"pixels\"', '\"points\"',\n                                          '\"axes min\"', '\"axes max\"']):\n    ax2.annotate(text, xy=(x, 0), xycoords=ax2.get_xaxis_transform(),\n                 bbox=dict(boxstyle=\"round\", fc=\"w\"), ha=\"left\", fontsize=8,\n                 annotation_clip=True)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(nrows=2, sharex=True)\nfig.suptitle(\"AngleLabel keyword arguments\")\nfig.canvas.draw()  # Need to draw the figure to define renderer\n\n# Showcase different text positions.\nax1.margins(y=0.4)\nax1.set_title(\"textposition\")\nkw = dict(size=75, unit=\"points\", text=r\"$60°$\")\n\nam6 = plot_angle(ax1, (2.0, 0), 60, textposition=\"inside\", **kw)\nam7 = plot_angle(ax1, (3.5, 0), 60, textposition=\"outside\", **kw)\nam8 = plot_angle(ax1, (5.0, 0), 60, textposition=\"edge\",\n                 text_kw=dict(bbox=dict(boxstyle=\"round\", fc=\"w\")), **kw)\nam9 = plot_angle(ax1, (6.5, 0), 60, textposition=\"edge\",\n                 text_kw=dict(xytext=(30, 20), arrowprops=dict(arrowstyle=\"->\",\n                              connectionstyle=\"arc3,rad=-0.2\")), **kw)\n\nfor x, text in zip([2.0, 3.5, 5.0, 6.5], ['\"inside\"', '\"outside\"', '\"edge\"',\n                                          '\"edge\", custom arrow']):\n    ax1.annotate(text, xy=(x, 0), xycoords=ax1.get_xaxis_transform(),\n                 bbox=dict(boxstyle=\"round\", fc=\"w\"), ha=\"left\", fontsize=8,\n                 annotation_clip=True)\n\n# Showcase different size units. The effect of this can best be observed\n# by interactively changing the figure size\nax2.margins(y=0.4)\nax2.set_title(\"unit\")\nkw = dict(text=r\"$60°$\", textposition=\"outside\")\n\nam10 = plot_angle(ax2, (2.0, 0), 60, size=50, unit=\"pixels\", **kw)\nam11 = plot_angle(ax2, (3.5, 0), 60, size=50, unit=\"points\", **kw)\nam12 = plot_angle(ax2, (5.0, 0), 60, size=0.25, unit=\"axes min\", **kw)\nam13 = plot_angle(ax2, (6.5, 0), 60, size=0.25, unit=\"axes max\", **kw)\n\nfor x, text in zip([2.0, 3.5, 5.0, 6.5], ['\"pixels\"', '\"points\"',\n                                          '\"axes min\"', '\"axes max\"']):\n    ax2.annotate(text, xy=(x, 0), xycoords=ax2.get_xaxis_transform(),\n                 bbox=dict(boxstyle=\"round\", fc=\"w\"), ha=\"left\", fontsize=8,\n                 annotation_clip=True)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-add-angle-annotations-to-matplotlib-arrows":{"intro":"In this lab, you will learn how to add angle annotations to bracket arrow styles created using FancyArrowPatch in Matplotlib. Angle annotations are useful for indicating the direction and size of angles in a plot. By the end of this lab, you will be able to create bracket arrow styles with angle annotations and customize them to fit your specific needs.","steps":[{"title":"Import necessary libraries and set up plot","body":["Import necessary libraries and set up plot","First, we need to import the necessary libraries and set up the plot. We will be using matplotlib.pyplot and numpy. We will also create a figure and an axis object to plot our data on."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.patches import FancyArrowPatch\n\nfig, ax = plt.subplots()\nax.set(xlim=(0, 6), ylim=(-1, 5))\nax.set_title(\"Orientation of the bracket arrows relative to angleA and angleB\")"}]},{"title":"Define a function to get the point of a rotated vertical line","body":["Define a function to get the point of a rotated vertical line","We will define a function that takes the origin coordinates, line length, and angle in degrees as inputs and returns the xy coordinates of the vertical line end rotated by the specified angle."],"code":[{"lang":"python","text":"def get_point_of_rotated_vertical(origin, line_length, degrees):\n    \"\"\"Return xy coordinates of the vertical line end rotated by degrees.\"\"\"\n    rad = np.deg2rad(-degrees)\n    return [origin[0] + line_length * np.sin(rad),\n            origin[1] + line_length * np.cos(rad)]"}]},{"title":"Create bracket arrows with angle annotations","body":["Create bracket arrows with angle annotations","We will create three bracket arrow styles with angle annotations using FancyArrowPatch. Each bracket arrow will have a different angle value for _angleA_ and _angleB_. We will also add vertical lines to indicate the position of the angle annotations."],"code":[{"lang":"python","text":"style = ']-['\nfor i, angle in enumerate([-40, 0, 60]):\n    y = 2*i\n    arrow_centers = ((1, y), (5, y))\n    vlines = ((1, y + 0.5), (5, y + 0.5))\n    anglesAB = (angle, -angle)\n    bracketstyle = f\"{style}, angleA={anglesAB[0]}, angleB={anglesAB[1]}\"\n    bracket = FancyArrowPatch(*arrow_centers, arrowstyle=bracketstyle,\n                              mutation_scale=42)\n    ax.add_patch(bracket)\n    ax.text(3, y + 0.05, bracketstyle, ha=\"center\", va=\"bottom\", fontsize=14)\n    ax.vlines([line[0] for line in vlines], [y, y], [line[1] for line in vlines],\n              linestyles=\"--\", color=\"C0\")"}]},{"title":"Add angle annotation arrows and text","body":["Add angle annotation arrows and text","We will add angle annotation arrows and text to each bracket arrow style. First, we will get the top coordinates for the drawn patches at _angleA_ and _angleB_. Then, we will define the connection directions for the annotation arrows. Finally, we will add arrows and annotation text to the plot."],"code":[{"lang":"python","text":"# Get the top coordinates for the drawn patches at A and B\n    patch_tops = [get_point_of_rotated_vertical(center, 0.5, angle)\n                  for center, angle in zip(arrow_centers, anglesAB)]\n    # Define the connection directions for the annotation arrows\n    connection_dirs = (1, -1) if angle > 0 else (-1, 1)\n    # Add arrows and annotation text\n    arrowstyle = \"Simple, tail_width=0.5, head_width=4, head_length=8\"\n    for vline, dir, patch_top, angle in zip(vlines, connection_dirs,\n                                            patch_tops, anglesAB):\n        kw = dict(connectionstyle=f\"arc3,rad={dir * 0.5}\",\n                  arrowstyle=arrowstyle, color=\"C0\")\n        ax.add_patch(FancyArrowPatch(vline, patch_top, **kw))\n        ax.text(vline[0] - dir * 0.15, y + 0.7, f'{angle}°', ha=\"center\",\n                va=\"center\")"}]},{"title":"Display the plot","body":["We will display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-animated-plots-with-matplotlib":{"intro":"Matplotlib is a data visualization library used to create static, animated, and interactive visualizations in Python. In this lab, we will learn how to create an animated plot using Matplotlib. We will use the FuncAnimation class to create an animation of a decaying sine wave.","steps":[{"title":"Import libraries","body":["First, we need to import the necessary libraries. We will be using Matplotlib and NumPy in this lab."],"code":[{"lang":"python","text":"import itertools\n\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib.animation as animation"}]},{"title":"Create the data generator function","body":["Create the data generator function","Next, we need to create a function to generate the data for the animation. The function will produce a sine wave that decays over time. We will use the itertools.count() function to generate an infinite sequence of numbers. We will use these numbers to calculate the values of the sine wave."],"code":[{"lang":"python","text":"def data_gen():\n    for cnt in itertools.count():\n        t = cnt / 10\n        yield t, np.sin(2*np.pi*t) * np.exp(-t/10.)"}]},{"title":"Set up the plot","body":["Now, we need to set up the plot. We will create a figure and an axes object using Matplotlib's subplots() function. We will also create a line object to represent the sine wave."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nline, = ax.plot([], [], lw=2)\nax.grid()\nxdata, ydata = [], []"}]},{"title":"Define the initialization function","body":["Define the initialization function","We need to define an initialization function that will set the initial state of the plot. In this function, we will set the y-axis limits and clear the data from the line object."],"code":[{"lang":"python","text":"def init():\n    ax.set_ylim(-1.1, 1.1)\n    ax.set_xlim(0, 1)\n    del xdata[:]\n    del ydata[:]\n    line.set_data(xdata, ydata)\n    return line,"}]},{"title":"Define the animation function","body":["Now, we need to define the function that will update the plot for each frame of the animation. This function will take the data generated by the data_gen() function and update the plot with the new data. We will also update the x-axis limits as the animation progresses."],"code":[{"lang":"python","text":"def run(data):\n    # update the data\n    t, y = data\n    xdata.append(t)\n    ydata.append(y)\n    xmin, xmax = ax.get_xlim()\n\n    if t >= xmax:\n        ax.set_xlim(xmin, 2*xmax)\n        ax.figure.canvas.draw()\n    line.set_data(xdata, ydata)\n\n    return line,"}]},{"title":"Create the animation","body":["Finally, we can create the animation using the FuncAnimation class. We will pass the fig, run, data_gen, init_func, and interval parameters to create the animation. We will also set the save_count parameter to 100 to ensure that only the last 100 frames are saved."],"code":[{"lang":"python","text":"ani = animation.FuncAnimation(fig, run, data_gen, interval=100, init_func=init,\n                              save_count=100)"}]},{"title":"Show the plot","body":["We can now show the plot using Matplotlib's show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-animated-histogram-using-matplotlib":{"intro":"In this lab, you will learn how to create an animated histogram using Matplotlib in Python. The animated histogram will simulate new data coming in and update the heights of rectangles with the new data.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.animation as animation"}]},{"title":"Set Random Seed and Bins","body":["Set random seed for reproducibility and fix the bin edges."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Fixing bin edges\nHIST_BINS = np.linspace(-4, 4, 100)"}]},{"title":"Create Data and Histogram","body":["Create data and histogram using NumPy."],"code":[{"lang":"python","text":"# histogram our data with numpy\ndata = np.random.randn(1000)\nn, _, _ = plt.hist(data, HIST_BINS, lw=1, ec=\"yellow\", fc=\"green\", alpha=0.5)"}]},{"title":"Create Animation Function","body":["We need to create an animate function that generates new random data and updates the heights of rectangles."],"code":[{"lang":"python","text":"def animate(frame_number):\n    # simulate new data coming in\n    data = np.random.randn(1000)\n    n, _ = np.histogram(data, HIST_BINS)\n    for count, rect in zip(n, bar_container.patches):\n        rect.set_height(count)\n    return bar_container.patches"}]},{"title":"Create Bar Container and Animation","body":["Create Bar Container and Animation","Using plt.hist allows us to get an instance of BarContainer, which is a collection of Rectangle instances. We use FuncAnimation to setup the animation."],"code":[{"lang":"python","text":"# Using plt.hist allows us to get an instance of BarContainer, which is a\n# collection of Rectangle instances. Calling prepare_animation will define\n# animate function working with supplied BarContainer, all this is used to setup FuncAnimation.\nfig, ax = plt.subplots()\n_, _, bar_container = ax.hist(data, HIST_BINS, lw=1, ec=\"yellow\", fc=\"green\", alpha=0.5)\nax.set_ylim(top=55)  # set safe limit to ensure that all data is visible.\n\nani = animation.FuncAnimation(fig, animate, 50, repeat=False, blit=True)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Using plt.hist allows us to get an instance of BarContainer, which is a\n# collection of Rectangle instances. Calling prepare_animation will define\n# animate function working with supplied BarContainer, all this is used to setup FuncAnimation.\nfig, ax = plt.subplots()\n_, _, bar_container = ax.hist(data, HIST_BINS, lw=1, ec=\"yellow\", fc=\"green\", alpha=0.5)\nax.set_ylim(top=55)  # set safe limit to ensure that all data is visible.\n\nani = animation.FuncAnimation(fig, animate, 50, repeat=False, blit=True)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-simple-matplotlib-animation-tutorial":{"intro":"This tutorial will guide you through how to create a simple animation using matplotlib.pyplot. Animations can be useful for visualizing data that changes over time. In this tutorial, we will generate a random set of data and display it as an animation.","steps":[{"title":"Import necessary libraries","body":["We need to import the necessary libraries to generate our animation. We will use numpy to generate random data and matplotlib.pyplot to display it as an animation."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate random data","body":["We will generate a 3D array of random data using numpy.random.random(). We will use a seed value to ensure that the same set of data is generated each time the code is run."],"code":[{"lang":"python","text":"np.random.seed(19680801)\ndata = np.random.random((50, 50, 50))"}]},{"title":"Create the animation","body":["We will use a for loop to iterate through each frame of the animation. In each iteration, we will clear the axis, plot the current frame, set the title, and pause for a short amount of time to allow the animation to be displayed."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nfor i, img in enumerate(data):\n    ax.clear()\n    ax.imshow(img)\n    ax.set_title(f\"frame {i}\")\n    plt.pause(0.1)"}]},{"title":"Display the animation","body":["We can display the animation by running the code. The animation will be displayed in a new window."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotated-matplotlib-plots-in-python":{"intro":"This tutorial will guide you through the process of creating a plot with annotations using Matplotlib in Python. You will learn how to connect two points with an arrow, add an ellipse to the plot, and customize the arrow style and ellipse properties.","steps":[{"title":"Set up the plot","body":["First, we need to set up the plot with two subplots. We will use the subplots function to create a 2x2 grid of subplots, and then we will define the x and y coordinates of two points."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\n\nfig, axs = plt.subplots(2, 2)\nx1, y1 = 0.3, 0.3\nx2, y2 = 0.7, 0.7"}]},{"title":"Connect two points with an arrow","body":["Connect two points with an arrow","In this step, we will connect the two points with an arrow. We will use the annotate function to create the arrow, and we will customize the arrow style and color."],"code":[{"lang":"python","text":"ax = axs.flat[0]\nax.plot([x1, x2], [y1, y2], \".\")\nax.annotate(\"\",\n            xy=(x1, y1), xycoords='data',\n            xytext=(x2, y2), textcoords='data',\n            arrowprops=dict(arrowstyle=\"-\",\n                            color=\"0.5\",\n                            connectionstyle=\"arc3,rad=0.3\",\n                            ),\n            )"}]},{"title":"Add an ellipse to the plot","body":["In this step, we will add an ellipse to the plot. We will use the Ellipse function to create the ellipse, and we will customize the ellipse properties such as the position, width, height, and angle."],"code":[{"lang":"python","text":"ax = axs.flat[1]\nax.plot([x1, x2], [y1, y2], \".\")\nel = mpatches.Ellipse((x1, y1), 0.3, 0.4, angle=30, alpha=0.2)\nax.add_artist(el)"}]},{"title":"Customize the arrow to connect to the ellipse","body":["Customize the arrow to connect to the ellipse","In this step, we will customize the arrow to connect to the ellipse. We will use the arrowprops parameter to specify that the arrow should connect to the ellipse, and we will also customize the arrow style and color."],"code":[{"lang":"python","text":"ax = axs.flat[2]\nax.plot([x1, x2], [y1, y2], \".\")\nel = mpatches.Ellipse((x1, y1), 0.3, 0.4, angle=30, alpha=0.2)\nax.add_artist(el)\nax.annotate(\"\",\n            xy=(x1, y1), xycoords='data',\n            xytext=(x2, y2), textcoords='data',\n            arrowprops=dict(arrowstyle=\"-\",\n                            color=\"0.5\",\n                            patchB=el,\n                            connectionstyle=\"arc3,rad=0.3\",\n                            ),\n            )"}]},{"title":"Customize the arrow to shrink to the ellipse","body":["Customize the arrow to shrink to the ellipse","In this step, we will customize the arrow to shrink to the ellipse. We will use the shrinkB parameter to specify the amount by which the arrow should shrink towards the ellipse."],"code":[{"lang":"python","text":"ax = axs.flat[3]\nax.plot([x1, x2], [y1, y2], \".\")\nel = mpatches.Ellipse((x1, y1), 0.3, 0.4, angle=30, alpha=0.2)\nax.add_artist(el)\nax.annotate(\"\",\n            xy=(x1, y1), xycoords='data',\n            xytext=(x2, y2), textcoords='data',\n            arrowprops=dict(arrowstyle=\"fancy\",\n                            color=\"0.5\",\n                            patchB=el,\n                            shrinkB=5,\n                            connectionstyle=\"arc3,rad=0.3\",\n                            ),\n            )"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = axs.flat[3]\nax.plot([x1, x2], [y1, y2], \".\")\nel = mpatches.Ellipse((x1, y1), 0.3, 0.4, angle=30, alpha=0.2)\nax.add_artist(el)\nax.annotate(\"\",\n            xy=(x1, y1), xycoords='data',\n            xytext=(x2, y2), textcoords='data',\n            arrowprops=dict(arrowstyle=\"fancy\",\n                            color=\"0.5\",\n                            patchB=el,\n                            shrinkB=5,\n                            connectionstyle=\"arc3,rad=0.3\",\n                            ),\n            )"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotate-text-arrow":{"intro":"This tutorial will guide you through creating an annotated scatter plot with a text arrow using Matplotlib in Python.","steps":[{"title":"Import libraries and generate random data","body":["Import libraries and generate random data","First, we need to import the necessary libraries and generate some random data for our scatter plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nfig, ax = plt.subplots(figsize=(5, 5))\nax.set_aspect(1)\n\nx1 = -1 + np.random.randn(100)\ny1 = -1 + np.random.randn(100)\nx2 = 1. + np.random.randn(100)\ny2 = 1. + np.random.randn(100)\n\nax.scatter(x1, y1, color=\"r\")\nax.scatter(x2, y2, color=\"g\")"}]},{"title":"Add text annotations to the plot","body":["Add text annotations to the plot","Next, we'll add text annotations to the plot using the ax.text() function. We'll create two annotations, one for \"Sample A\" and one for \"Sample B\"."],"code":[{"lang":"python","text":"bbox_props = dict(boxstyle=\"round\", fc=\"w\", ec=\"0.5\", alpha=0.9)\nax.text(-2, -2, \"Sample A\", ha=\"center\", va=\"center\", size=20,\n        bbox=bbox_props)\nax.text(2, 2, \"Sample B\", ha=\"center\", va=\"center\", size=20,\n        bbox=bbox_props)"}]},{"title":"Add a text arrow to indicate direction","body":["Add a text arrow to indicate direction","To indicate the direction of the data, we'll add a text arrow using the ax.text() function and the bbox parameter with the boxstyle set to \"rarrow\"."],"code":[{"lang":"python","text":"bbox_props = dict(boxstyle=\"rarrow\", fc=(0.8, 0.9, 0.9), ec=\"b\", lw=2)\nt = ax.text(0, 0, \"Direction\", ha=\"center\", va=\"center\", rotation=45,\n            size=15,\n            bbox=bbox_props)\n\nbb = t.get_bbox_patch()\nbb.set_boxstyle(\"rarrow\", pad=0.6)"}]},{"title":"Set plot limits and show the plot","body":["Set plot limits and show the plot","Finally, we'll set the x and y limits of the plot and show the plot using the ax.set_xlim(), ax.set_ylim(), and plt.show() functions."],"code":[{"lang":"python","text":"ax.set_xlim(-4, 4)\nax.set_ylim(-4, 4)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set_xlim(-4, 4)\nax.set_ylim(-4, 4)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotating-matplotlib-plots-with-coordinate-":{"intro":"Matplotlib is a powerful visualization tool that allows users to create a wide variety of plots and charts. Annotations are an important feature of Matplotlib that allow users to add text and arrows to their plots. In this tutorial, we will learn how to use different coordinate systems for annotations.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. We will be using the matplotlib.pyplot library to create our plot and annotations."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we will create some data to plot. We will be using the numpy library to create a sine wave."],"code":[{"lang":"python","text":"x = np.arange(0, 10, 0.005)\ny = np.exp(-x/2.) * np.sin(2*np.pi*x)"}]},{"title":"Create the Plot","body":["Now, we will create the plot using the matplotlib.pyplot library. We will set the x and y limits of the plot and then plot the data."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(x, y)\nax.set_xlim(0, 10)\nax.set_ylim(-1, 1)"}]},{"title":"Transform Coordinates","body":["The next step is to transform the coordinates of the data and the display. We will use the ax.transData method to transform the data coordinates and the figure pixels coordinate system to transform the display coordinates."],"code":[{"lang":"python","text":"xdata, ydata = 5, 0\nxdisplay, ydisplay = ax.transData.transform((xdata, ydata))"}]},{"title":"Add Annotations","body":["The final step is to add annotations to the plot. We will use the ax.annotate method to add text and arrows to the plot. We will also use the bbox and arrowprops parameters to style the annotations."],"code":[{"lang":"python","text":"bbox = dict(boxstyle=\"round\", fc=\"0.8\")\narrowprops = dict(\n    arrowstyle=\"->\",\n    connectionstyle=\"angle,angleA=0,angleB=90,rad=10\")\n\noffset = 72\nax.annotate(\n    f'data = ({xdata:.1f}, {ydata:.1f})',\n    (xdata, ydata),\n    xytext=(-2*offset, offset), textcoords='offset points',\n    bbox=bbox, arrowprops=arrowprops)\nax.annotate(\n    f'display = ({xdisplay:.1f}, {ydisplay:.1f})',\n    xy=(xdisplay, ydisplay), xycoords='figure pixels',\n    xytext=(0.5*offset, -offset), textcoords='offset points',\n    bbox=bbox, arrowprops=arrowprops)"}]},{"title":"Show the Plot","body":["The final step is to show the plot using the plt.show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotate-with-units":{"intro":"This tutorial will guide you through the process of creating text and arrow annotations using a centimeter-scale plot in Python Matplotlib.","steps":[{"title":"Import necessary libraries and define units","body":["Import necessary libraries and define units","In this step, we will import the necessary libraries and define the unit of measurement that we will be using for our plot."],"code":[{"lang":"python","text":"from basic_units import cm\nimport matplotlib.pyplot as plt"}]},{"title":"Create a plot","body":["In this step, we will create a plot using the subplots() function and store it in the fig and ax variables."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Add text annotation","body":["In this step, we will add a text annotation to the plot using the annotate() function. We will provide the position of the annotation and the text to be displayed."],"code":[{"lang":"python","text":"ax.annotate(\"Note 01\", [0.5*cm, 0.5*cm])"}]},{"title":"Add arrow annotation with unitized xy and text","body":["Add arrow annotation with unitized xy and text","In this step, we will add an arrow annotation to the plot using the annotate() function. We will provide the position of the arrow, the text to be displayed, and the arrow properties. We will also specify the units of measurement for the position and text."],"code":[{"lang":"python","text":"ax.annotate('local max', xy=(3*cm, 1*cm), xycoords='data',\n            xytext=(0.8*cm, 0.95*cm), textcoords='data',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='right', verticalalignment='top')"}]},{"title":"Add arrow annotation with mixed units","body":["Add arrow annotation with mixed units","In this step, we will add another arrow annotation to the plot using the annotate() function. We will provide the position of the arrow, the text to be displayed, and the arrow properties. We will also mix units of measurement for the position and use the axes fraction for the text."],"code":[{"lang":"python","text":"ax.annotate('local max', xy=(3*cm, 1*cm), xycoords='data',\n            xytext=(0.8, 0.95), textcoords='axes fraction',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='right', verticalalignment='top')"}]},{"title":"Set plot limits and display the plot","body":["Set plot limits and display the plot","In this step, we will set the limits of the plot and display it using the set_xlim(), set_ylim(), and show() functions."],"code":[{"lang":"python","text":"ax.set_xlim(0*cm, 4*cm)\nax.set_ylim(0*cm, 4*cm)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set_xlim(0*cm, 4*cm)\nax.set_ylim(0*cm, 4*cm)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-data-cursor-with-matplotlib":{"intro":"In this lab, we will learn how to create a data cursor including a text box, which shows the plot point close to the mouse pointer using Matplotlib, a plotting library for the Python programming language.","steps":[{"title":"Import necessary libraries","body":["We start by importing Matplotlib and NumPy libraries. NumPy is the fundamental package for scientific computing in Python, while Matplotlib is a plotting library that produces publication-quality figures."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a plot","body":["We create a simple plot of a parabola using NumPy's linspace function to generate 1000 values between -5 and 5 for x, and then compute y as the square of x."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(8, 6))\nax.set_title(\"Cursor Tracking x Position\")\n\nx = np.linspace(-5, 5, 1000)\ny = x**2\n\nline, = ax.plot(x, y)\nax.set_xlim(-5, 5)\nax.set_ylim(0, 25)"}]},{"title":"Create the AnnotatedCursor class","body":["Create the AnnotatedCursor class"],"code":[{"lang":"python","text":"class AnnotatedCursor(Cursor):\n    \"\"\"\n    A crosshair cursor like `~matplotlib.widgets.Cursor` with a text showing \\\n    the current coordinates.\n    ...\n    \"\"\""}]},{"title":"Initialize the AnnotatedCursor object","body":["Initialize the AnnotatedCursor object","We initialize the AnnotatedCursor object by passing the plot line, line, to the AnnotatedCursor constructor."],"code":[{"lang":"python","text":"cursor = AnnotatedCursor(line=line, ax=ax, useblit=True)"}]},{"title":"Display the plot","body":["We display the plot using the show() method of the Matplotlib pyplot module."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotating-a-plot-using-matplotlib":{"intro":"This tutorial will guide you through the process of annotating a plot using Matplotlib. Annotating a plot is a useful way to highlight specific features or data points on a graph. In this tutorial, we will demonstrate how to annotate a plot with an arrow pointing to provided coordinates.","steps":[{"title":"Import Libraries","body":["Before we begin, we need to import the necessary libraries. In this tutorial, we will be using Matplotlib and Numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a Plot","body":["Next, we will create a plot using Matplotlib. In this example, we will plot the cosine function over a range of values."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\n\nt = np.arange(0.0, 5.0, 0.01)\ns = np.cos(2*np.pi*t)\nline, = ax.plot(t, s, lw=2)"}]},{"title":"Annotate the Plot","body":["Now, we will annotate the plot by adding an arrow pointing to a specific coordinate. In this example, we will add an arrow pointing to the local maximum of the cosine function.","The ax.annotate() function takes several arguments. The first argument is the text that will be displayed on the plot. The xy argument specifies the coordinates of the point that we want to annotate. The xytext argument specifies the coordinates of the text. The arrowprops argument is a dictionary that specifies the properties of the arrow."],"code":[{"lang":"python","text":"ax.annotate('local max', xy=(2, 1), xytext=(3, 1.5),\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            )"}]},{"title":"Set the Plot Limits","body":["Finally, we will set the limits of the plot to ensure that the annotated point is visible."],"code":[{"lang":"python","text":"ax.set_ylim(-2, 2)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax.set_ylim(-2, 2)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotate-matplotlib-plots-effectively":{"intro":"This lab will guide you through annotating plots in Matplotlib. You will learn how to highlight specific points of interest and use various visual tools to call attention to these points. Annotation and text tools are essential for conveying information and making plots more visually appealing.","steps":[{"title":"Specifying text points and annotation points","body":["Specifying text points and annotation points","You must specify an annotation point xy=(x, y) to annotate this point. Additionally, you may specify a text point xytext=(x, y) for the location of the text for this annotation. Optionally, you can specify the coordinate system of xy and xytext with one of the following strings for xycoords and textcoords (default is 'data'):","• 'figure points' : points from the lower left corner of the figure • 'figure pixels' : pixels from the lower left corner of the figure • 'figure fraction' : (0, 0) is lower left of figure and (1, 1) is upper right • 'axes points' : points from lower left corner of axes • 'axes pixels' : pixels from lower left corner of axes • 'axes fraction' : (0, 0) is lower left of axes and (1, 1) is upper right • 'offset points' : Specify an offset (in points) from the xy value • 'offset pixels' : Specify an offset (in pixels) from the xy value • 'data' : use the axes data coordinate system","Note: for physical coordinate systems (points or pixels) the origin is the (bottom, left) of the figure or axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.patches import Ellipse\nfrom matplotlib.text import OffsetFrom\n\n# Create our figure and data we'll use for plotting\nfig, ax = plt.subplots(figsize=(4, 4))\n\nt = np.arange(0.0, 5.0, 0.01)\ns = np.cos(2*np.pi*t)\n\n# Plot a line and add some simple annotations\nline, = ax.plot(t, s)\nax.annotate('figure pixels',\n            xy=(10, 10), xycoords='figure pixels')\nax.annotate('figure points',\n            xy=(107, 110), xycoords='figure points',\n            fontsize=12)\nax.annotate('figure fraction',\n            xy=(.025, .975), xycoords='figure fraction',\n            horizontalalignment='left', verticalalignment='top',\n            fontsize=20)\n\n# The following examples show off how these arrows are drawn.\n\nax.annotate('point offset from data',\n            xy=(3, 1), xycoords='data',\n            xytext=(-10, 90), textcoords='offset points',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='center', verticalalignment='bottom')\n\nax.annotate('axes fraction',\n            xy=(2, 1), xycoords='data',\n            xytext=(0.36, 0.68), textcoords='axes fraction',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='right', verticalalignment='top')\n\n# You may also use negative points or pixels to specify from (right, top).\n# E.g., (-10, 10) is 10 points to the left of the right side of the axes and 10\n# points above the bottom\n\nax.annotate('pixel offset from axes fraction',\n            xy=(1, 0), xycoords='axes fraction',\n            xytext=(-20, 20), textcoords='offset pixels',\n            horizontalalignment='right',\n            verticalalignment='bottom')"}]},{"title":"Using multiple coordinate systems and axis types","body":["Using multiple coordinate systems and axis types","You can specify the xypoint and the xytext in different positions and coordinate systems, and optionally turn on a connecting line and mark the point with a marker. Annotations work on polar axes too."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(subplot_kw=dict(projection='polar'), figsize=(3, 3))\nr = np.arange(0, 1, 0.001)\ntheta = 2*2*np.pi*r\nline, = ax.plot(theta, r)\n\nind = 800\nthisr, thistheta = r[ind], theta[ind]\nax.plot([thistheta], [thisr], 'o')\nax.annotate('a polar annotation',\n            xy=(thistheta, thisr),  # theta, radius\n            xytext=(0.05, 0.05),    # fraction, fraction\n            textcoords='figure fraction',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='left',\n            verticalalignment='bottom')"}]},{"title":"Customizing arrow and bubble styles","body":["Customizing arrow and bubble styles","The arrow between xytext and the annotation point, as well as the bubble that covers the annotation text, are highly customizable. Below are a few parameter options as well as their resulting output."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(8, 5))\n\nt = np.arange(0.0, 5.0, 0.01)\ns = np.cos(2*np.pi*t)\nline, = ax.plot(t, s, lw=3)\n\nax.annotate(\n    'straight',\n    xy=(0, 1), xycoords='data',\n    xytext=(-50, 30), textcoords='offset points',\n    arrowprops=dict(arrowstyle=\"->\"))\nax.annotate(\n    'arc3,\\nrad 0.2',\n    xy=(0.5, -1), xycoords='data',\n    xytext=(-80, -60), textcoords='offset points',\n    arrowprops=dict(arrowstyle=\"->\",\n                    connectionstyle=\"arc3,rad=.2\"))\nax.annotate(\n    'arc,\\nangle 50',\n    xy=(1., 1), xycoords='data',\n    xytext=(-90, 50), textcoords='offset points',\n    arrowprops=dict(arrowstyle=\"->\",\n                    connectionstyle=\"arc,angleA=0,armA=50,rad=10\"))\nax.annotate(\n    'arc,\\narms',\n    xy=(1.5, -1), xycoords='data',\n    xytext=(-80, -60), textcoords='offset points',\n    arrowprops=dict(\n        arrowstyle=\"->\",\n        connectionstyle=\"arc,angleA=0,armA=40,angleB=-90,armB=30,rad=7\"))\nax.annotate(\n    'angle,\\nangle 90',\n    xy=(2., 1), xycoords='data',\n    xytext=(-70, 30), textcoords='offset points',\n    arrowprops=dict(arrowstyle=\"->\",\n                    connectionstyle=\"angle,angleA=0,angleB=90,rad=10\"))\nax.annotate(\n    'angle3,\\nangle -90',\n    xy=(2.5, -1), xycoords='data',\n    xytext=(-80, -60), textcoords='offset points',\n    arrowprops=dict(arrowstyle=\"->\",\n                    connectionstyle=\"angle3,angleA=0,angleB=-90\"))\nax.annotate(\n    'angle,\\nround',\n    xy=(3., 1), xycoords='data',\n    xytext=(-60, 30), textcoords='offset points',\n    bbox=dict(boxstyle=\"round\", fc=\"0.8\"),\n    arrowprops=dict(arrowstyle=\"->\","}]},{"title":"More examples of coordinate systems","body":["More examples of coordinate systems","Below we'll show a few more examples of coordinate systems and how the location of annotations may be specified."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\n\nbbox_args = dict(boxstyle=\"round\", fc=\"0.8\")\narrow_args = dict(arrowstyle=\"->\")\n\n# Here we'll demonstrate the extents of the coordinate system and how\n# we place annotating text.\n\nax1.annotate('figure fraction : 0, 0', xy=(0, 0), xycoords='figure fraction',\n             xytext=(20, 20), textcoords='offset points',\n             ha=\"left\", va=\"bottom\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('figure fraction : 1, 1', xy=(1, 1), xycoords='figure fraction',\n             xytext=(-20, -20), textcoords='offset points',\n             ha=\"right\", va=\"top\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('axes fraction : 0, 0', xy=(0, 0), xycoords='axes fraction',\n             xytext=(20, 20), textcoords='offset points',\n             ha=\"left\", va=\"bottom\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('axes fraction : 1, 1', xy=(1, 1), xycoords='axes fraction',\n             xytext=(-20, -20), textcoords='offset points',\n             ha=\"right\", va=\"top\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\n# It is also possible to generate draggable annotations\n\nan1 = ax1.annotate('Drag me 1', xy=(.5, .7), xycoords='data',\n                   ha=\"center\", va=\"center\",\n                   bbox=bbox_args)\n\nan2 = ax1.annotate('Drag me 2', xy=(.5, .5), xycoords=an1,\n                   xytext=(.5, .3), textcoords='axes fraction',\n                   ha=\"center\", va=\"center\",\n                   bbox=bbox_args,\n                   arrowprops=dict(patchB=an1.get_bbox_patch(),\n                                   connectionstyle=\"arc3,rad=0.2\",\n                                   **arrow_args))\nan1.draggable()\nan2.draggable()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\n\nbbox_args = dict(boxstyle=\"round\", fc=\"0.8\")\narrow_args = dict(arrowstyle=\"->\")\n\n# Here we'll demonstrate the extents of the coordinate system and how\n# we place annotating text.\n\nax1.annotate('figure fraction : 0, 0', xy=(0, 0), xycoords='figure fraction',\n             xytext=(20, 20), textcoords='offset points',\n             ha=\"left\", va=\"bottom\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('figure fraction : 1, 1', xy=(1, 1), xycoords='figure fraction',\n             xytext=(-20, -20), textcoords='offset points',\n             ha=\"right\", va=\"top\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('axes fraction : 0, 0', xy=(0, 0), xycoords='axes fraction',\n             xytext=(20, 20), textcoords='offset points',\n             ha=\"left\", va=\"bottom\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\nax1.annotate('axes fraction : 1, 1', xy=(1, 1), xycoords='axes fraction',\n             xytext=(-20, -20), textcoords='offset points',\n             ha=\"right\", va=\"top\",\n             bbox=bbox_args,\n             arrowprops=arrow_args)\n\n# It is also possible to generate draggable annotations\n\nan1 = ax1.annotate('Drag me 1', xy=(.5, .7), xycoords='data',\n                   ha=\"center\", va=\"center\",\n                   bbox=bbox_args)\n\nan2 = ax1.annotate('Drag me 2', xy=(.5, .5), xycoords=an1,\n                   xytext=(.5, .3), textcoords='axes fraction',\n                   ha=\"center\", va=\"center\",\n                   bbox=bbox_args,\n                   arrowprops=dict(patchB=an1.get_bbox_patch(),\n                                   connectionstyle=\"arc3,rad=0.2\",\n                                   **arrow_args))\nan1.draggable()\nan2.draggable()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-polar-graphs-with-python-matplotlib":{"intro":"In this lab, you will learn how to create a polar graph and annotate it using Python Matplotlib library. A polar graph is a graph drawn using polar coordinates. It is useful for visualizing cyclic phenomena such as waves, seasons, and tides.","steps":[{"title":"Import Libraries","body":["To get started, we first need to import the necessary libraries. In this case, we need numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create a Polar Graph","body":["Next, we create a polar graph by defining the figure and specifying that it has a polar projection. We also define the radius and theta values to be used in plotting."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(projection='polar')\nr = np.arange(0, 1, 0.001)\ntheta = 2 * 2*np.pi * r\nline, = ax.plot(theta, r, color='#ee8d18', lw=3)"}]},{"title":"Add Annotation","body":["We can add an annotation to the polar graph by specifying the location of the annotation. In this case, we choose a specific point on the graph and annotate it."],"code":[{"lang":"python","text":"ind = 800\nthisr, thistheta = r[ind], theta[ind]\nax.plot([thistheta], [thisr], 'o')\nax.annotate('a polar annotation',\n            xy=(thistheta, thisr),  # theta, radius\n            xytext=(0.05, 0.05),    # fraction, fraction\n            textcoords='figure fraction',\n            arrowprops=dict(facecolor='black', shrink=0.05),\n            horizontalalignment='left',\n            verticalalignment='bottom',\n            )"}]},{"title":"Display the Graph","body":["We can now display the graph using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualizations-for-data-analysis":{"intro":"In this tutorial, you will learn how to use Matplotlib to create visualizations in Python. Matplotlib is a popular data visualization library in Python used to create a variety of charts and graphs. with Matplotlib, you can create line plots, scatter plots, bar plots, histograms, and many other types of visualizations.","steps":[{"title":"Import Matplotlib","body":["Before creating any visualization, we need to import the Matplotlib library. We will also use the NumPy library to generate some sample data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Sample Data","body":["Let's create some sample data that we will use to create visualizations. We will generate four sets of data, each with 11 x,y data points."],"code":[{"lang":"python","text":"x = [10, 8, 13, 9, 11, 14, 6, 4, 12, 7, 5]\ny1 = [8.04, 6.95, 7.58, 8.81, 8.33, 9.96, 7.24, 4.26, 10.84, 4.82, 5.68]\ny2 = [9.14, 8.14, 8.74, 8.77, 9.26, 8.10, 6.13, 3.10, 9.13, 7.26, 4.74]\ny3 = [7.46, 6.77, 12.74, 7.11, 7.81, 8.84, 6.08, 5.39, 8.15, 6.42, 5.73]\nx4 = [8, 8, 8, 8, 8, 8, 8, 19, 8, 8, 8]\ny4 = [6.58, 5.76, 7.71, 8.84, 8.47, 7.04, 5.25, 12.50, 5.56, 7.91, 6.89]"}]},{"title":"Create a Figure with Subplots","body":["Now we will create a figure with four subplots, one for each dataset. We will also set the x and y limits to be the same for all subplots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2, sharex=True, sharey=True, figsize=(6, 6),\n                        gridspec_kw={'wspace': 0.08, 'hspace': 0.08})\naxs[0, 0].set(xlim=(0, 20), ylim=(2, 14))\naxs[0, 0].set(xticks=(0, 10, 20), yticks=(4, 8, 12))"}]},{"title":"Plot the Data","body":["For each subplot, we will plot the x and y data points and add a linear regression line. We will also add a text box with some statistics about the data."],"code":[{"lang":"python","text":"datasets = {\n    'I': (x, y1),\n    'II': (x, y2),\n    'III': (x, y3),\n    'IV': (x4, y4)\n}\n\nfor ax, (label, (x, y)) in zip(axs.flat, datasets.items()):\n    ax.text(0.1, 0.9, label, fontsize=20, transform=ax.transAxes, va='top')\n    ax.tick_params(direction='in', top=True, right=True)\n    ax.plot(x, y, 'o')\n\n    # linear regression\n    p1, p0 = np.polyfit(x, y, deg=1)  # slope, intercept\n    ax.axline(xy1=(0, p0), slope=p1, color='r', lw=2)\n\n    # add text box for the statistics\n    stats = (f'$\\\\mu$ = {np.mean(y):.2f}\\n'\n             f'$\\\\sigma$ = {np.std(y):.2f}\\n'\n             f'$r$ = {np.corrcoef(x, y)[0][1]:.2f}')\n    bbox = dict(boxstyle='round', fc='blanchedalmond', ec='orange', alpha=0.5)\n    ax.text(0.95, 0.07, stats, fontsize=9, bbox=bbox,\n            transform=ax.transAxes, horizontalalignment='right')\n\nplt.show()"}]},{"title":"Interpret the Results","body":["The resulting visualization is a set of four subplots, each showing a different dataset. The x and y limits are the same for all subplots. Each subplot contains the x and y data points as well as a linear regression line. The text box in the lower right corner of each subplot shows some statistics about the data, including the mean, standard deviation, and correlation coefficient."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-arrow-plotting-using-matplotlib":{"intro":"Matplotlib is a powerful plotting library in Python. It provides a variety of customizable visualizations such as line plots, scatter plots, bar graphs, histograms, and more. One of the visualizations that Matplotlib provides is the Arrow Plot. Arrow plots are used to encode arrow 'strength' such as transition probabilities in a Markov model using arrow length, width, or alpha (opacity).","steps":[{"title":"Import Libraries and Define the Function","body":["Import Libraries and Define the Function","The first step is to import the necessary libraries and define the make_arrow_graph() function. This function takes in various parameters such as the axes, data, size, display, shape, max_arrow_width, arrow_sep, alpha, normalize_data, ec, labelcolor, and kwargs. It uses these parameters to create an arrow plot."],"code":[{"lang":"python","text":"# Import libraries\nimport itertools\nimport matplotlib.pyplot as plt\nimport numpy as np\n\n# Define the function\ndef make_arrow_graph(ax, data, size=4, display='length', shape='right',\n                     max_arrow_width=0.03, arrow_sep=0.02, alpha=0.5,\n                     normalize_data=False, ec=None, labelcolor=None,\n                     **kwargs):\n    \"\"\"\n    Makes an arrow plot.\n\n    Parameters\n    ----------\n    ax\n        The axes where the graph is drawn.\n    data\n        Dict with probabilities for the bases and pair transitions.\n    size\n        Size of the plot, in inches.\n    display : {'length', 'width', 'alpha'}\n        The arrow property to change.\n    shape : {'full', 'left', 'right'}\n        For full or half arrows.\n    max_arrow_width : float\n        Maximum width of an arrow, in data coordinates.\n    arrow_sep : float\n        Separation between arrows in a pair, in data coordinates.\n    alpha : float\n        Maximum opacity of arrows.\n    **kwargs\n        `.FancyArrow` properties, e.g. *linewidth* or *edgecolor*.\n    \"\"\"\n\n    # code block"}]},{"title":"Define the Data and Plot the Arrow Graph","body":["Define the Data and Plot the Arrow Graph","The second step is to define the data and plot the arrow graph using the make_arrow_graph() function. We will define the data as a dictionary with probabilities for the bases and pair transitions. We will also set the size of the plot to 4 and normalize the data."],"code":[{"lang":"python","text":"# Define the data\ndata = {\n    'A': 0.4, 'T': 0.3, 'G': 0.6, 'C': 0.2,\n    'AT': 0.4, 'AC': 0.3, 'AG': 0.2,\n    'TA': 0.2, 'TC': 0.3, 'TG': 0.4,\n    'CT': 0.2, 'CG': 0.3, 'CA': 0.2,\n    'GA': 0.1, 'GT': 0.4, 'GC': 0.1,\n}\n\n# Plot the arrow graph\nsize = 4\nfig = plt.figure(figsize=(3 * size, size), layout=\"constrained\")\naxs = fig.subplot_mosaic([[\"length\", \"width\", \"alpha\"]])\n\nfor display, ax in axs.items():\n    make_arrow_graph(\n        ax, data, display=display, linewidth=0.001, edgecolor=None,\n        normalize_data=True, size=size)\n\nplt.show()"}]},{"title":"Customize the Arrow Graph","body":["The third step is to customize the arrow graph. We can change the arrow property to display using the display parameter. We can also change the shape of the arrow using the shape parameter. We can adjust the width and separation of the arrows using the max_arrow_width and arrow_sep parameters, respectively. We can change the transparency of the arrows using the alpha parameter. We can also change the color of the label using the labelcolor parameter."],"code":[{"lang":"python","text":"# Plot the arrow graph with customizations\nsize = 4\nfig = plt.figure(figsize=(3 * size, size), layout=\"constrained\")\naxs = fig.subplot_mosaic([[\"length\", \"width\", \"alpha\"]])\n\nfor display, ax in axs.items():\n    make_arrow_graph(\n        ax, data, display=display, linewidth=0.001, edgecolor=None,\n        normalize_data=True, size=size, shape='full', max_arrow_width=0.05,\n        arrow_sep=0.03, alpha=0.7, labelcolor='white')\n\nplt.show()"}]},{"title":"Interpret the Arrow Graph","body":["The fourth step is to interpret the arrow graph. The length, width, and opacity of the arrows represent the arrow strength. The arrow graph can be used to encode arrow \"strength\" such as transition probabilities in a Markov model using arrow length, width, or alpha (opacity). The labels on the arrows represent the probabilities for the bases and pair transitions."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-arrow-guide":{"intro":"Arrows are often used to annotate plots. This tutorial shows how to plot arrows that behave differently when the data limits on a plot are changed.","steps":[{"title":"Head shape fixed in display space, anchor points fixed in data space","body":["Head shape fixed in display space, anchor points fixed in data space","This is useful if you are annotating a plot, and don't want the arrow to change shape or position if you pan or scale the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\n\nx_tail = 0.1\ny_tail = 0.5\nx_head = 0.9\ny_head = 0.8\ndx = x_head - x_tail\ndy = y_head - y_tail\n\nfig, axs = plt.subplots(nrows=2)\narrow = mpatches.FancyArrowPatch((x_tail, y_tail), (x_head, y_head),\n                                 mutation_scale=100)\naxs[0].add_patch(arrow)\n\narrow = mpatches.FancyArrowPatch((x_tail, y_tail), (x_head, y_head),\n                                 mutation_scale=100)\naxs[1].add_patch(arrow)\naxs[1].set(xlim=(0, 2), ylim=(0, 2))\n\nplt.show()"}]},{"title":"Head shape and anchor points fixed in display space","body":["Head shape and anchor points fixed in display space","This is useful if you are annotating a plot, and don't want the arrow to change shape or position if you pan or scale the plot."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2)\narrow = mpatches.FancyArrowPatch((x_tail, y_tail), (x_head, y_head),\n                                 mutation_scale=100,\n                                 transform=axs[0].transAxes)\naxs[0].add_patch(arrow)\n\narrow = mpatches.FancyArrowPatch((x_tail, y_tail), (x_head, y_head),\n                                 mutation_scale=100,\n                                 transform=axs[1].transAxes)\naxs[1].add_patch(arrow)\naxs[1].set(xlim=(0, 2), ylim=(0, 2))\n\nplt.show()"}]},{"title":"Entire patch fixed in data space","body":["Entire patch fixed in data space"],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2)\n\narrow = mpatches.Arrow(x_tail, y_tail, dx, dy)\naxs[0].add_patch(arrow)\n\narrow = mpatches.FancyArrow(x_tail, y_tail - .4, dx, dy,\n                            width=.1, length_includes_head=True, color=\"C1\")\naxs[0].add_patch(arrow)\n\naxs[0].arrow(x_tail + 1, y_tail - .4, dx, dy,\n             width=.1, length_includes_head=True, color=\"C2\")\n\narrow = mpatches.Arrow(x_tail, y_tail, dx, dy)\naxs[1].add_patch(arrow)\n\narrow = mpatches.FancyArrow(x_tail, y_tail - .4, dx, dy,\n                            width=.1, length_includes_head=True, color=\"C1\")\naxs[1].add_patch(arrow)\n\naxs[1].arrow(x_tail + 1, y_tail - .4, dx, dy,\n             width=.1, length_includes_head=True, color=\"C2\")\naxs[1].set(xlim=(0, 2), ylim=(0, 2))\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, axs = plt.subplots(nrows=2)\n\narrow = mpatches.Arrow(x_tail, y_tail, dx, dy)\naxs[0].add_patch(arrow)\n\narrow = mpatches.FancyArrow(x_tail, y_tail - .4, dx, dy,\n                            width=.1, length_includes_head=True, color=\"C1\")\naxs[0].add_patch(arrow)\n\naxs[0].arrow(x_tail + 1, y_tail - .4, dx, dy,\n             width=.1, length_includes_head=True, color=\"C2\")\n\narrow = mpatches.Arrow(x_tail, y_tail, dx, dy)\naxs[1].add_patch(arrow)\n\narrow = mpatches.FancyArrow(x_tail, y_tail - .4, dx, dy,\n                            width=.1, length_includes_head=True, color=\"C1\")\naxs[1].add_patch(arrow)\n\naxs[1].arrow(x_tail + 1, y_tail - .4, dx, dy,\n             width=.1, length_includes_head=True, color=\"C2\")\naxs[1].set(xlim=(0, 2), ylim=(0, 2))\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-drawing-shapes-with-matplotlib-in-python":{"intro":"In this lab, we will learn how to draw various shapes using Matplotlib library in Python. Matplotlib is a plotting library for the Python programming language and its numerical mathematics extension NumPy. It provides an object-oriented API for embedding plots into applications using general-purpose GUI toolkits like Tkinter, wxPython, Qt, or GTK.","steps":[{"title":"Import Libraries","body":["Before we start using Matplotlib, we need to import the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as mpatches\nimport matplotlib.path as mpath"}]},{"title":"Define Shapes","body":["We will define the shapes we want to draw using Matplotlib. In this example, we will draw a circle, a rectangle, a wedge, a regular polygon, an ellipse, an arrow, a path patch, and a fancy box patch."],"code":[{"lang":"python","text":"shapes = [\n    mpatches.Circle((0, 0), 0.1, ec=\"none\"),\n    mpatches.Rectangle((-0.025, -0.05), 0.05, 0.1, ec=\"none\"),\n    mpatches.Wedge((0, 0), 0.1, 30, 270, ec=\"none\"),\n    mpatches.RegularPolygon((0, 0), 5, radius=0.1),\n    mpatches.Ellipse((0, 0), 0.2, 0.1),\n    mpatches.Arrow(-0.05, -0.05, 0.1, 0.1, width=0.1),\n    mpatches.PathPatch(mpath.Path([(0, 0), (0.5, 0.5), (1, 0)], [1, 2, 2]), ec=\"none\"),\n    mpatches.FancyBboxPatch((-0.025, -0.05), 0.05, 0.1, ec=\"none\",\n                            boxstyle=mpatches.BoxStyle(\"Round\", pad=0.02)),\n]"}]},{"title":"Draw Shapes","body":["We will now draw the shapes using Matplotlib by iterating through the shapes list and adding them to the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfor shape in shapes:\n    ax.add_artist(shape)\nplt.xlim([-0.5, 1.5])\nplt.ylim([-0.5, 1.5])\nplt.axis('off')\nplt.show()"}]},{"title":"Customize Shapes","body":["We can customize the shapes by setting various properties such as color, edge color, and alpha."],"code":[{"lang":"python","text":"shapes = [\n    mpatches.Circle((0, 0), 0.1, color='red', alpha=0.5),\n    mpatches.Rectangle((-0.025, -0.05), 0.05, 0.1, ec=\"none\", color='green', alpha=0.5),\n    mpatches.Wedge((0, 0), 0.1, 30, 270, ec=\"none\", color='blue', alpha=0.5),\n    mpatches.RegularPolygon((0, 0), 5, radius=0.1, color='orange', alpha=0.5),\n    mpatches.Ellipse((0, 0), 0.2, 0.1, color='purple', alpha=0.5),\n    mpatches.Arrow(-0.05, -0.05, 0.1, 0.1, width=0.1, color='yellow', alpha=0.5),\n    mpatches.PathPatch(mpath.Path([(0, 0), (0.5, 0.5), (1, 0)], [1, 2, 2]), ec=\"none\", color='pink', alpha=0.5),\n    mpatches.FancyBboxPatch((-0.025, -0.05), 0.05, 0.1, ec=\"none\", color='brown', alpha=0.5,\n                            boxstyle=mpatches.BoxStyle(\"Round\", pad=0.02)),\n]\n\nfig, ax = plt.subplots()\nfor shape in shapes:\n    ax.add_artist(shape)\nplt.xlim([-0.5, 1.5])\nplt.ylim([-0.5, 1.5])\nplt.axis('off')\nplt.show()"}]},{"title":"Save Plot","body":["We can save the plot as an image file using the savefig function."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nfor shape in shapes:\n    ax.add_artist(shape)\nplt.xlim([-0.5, 1.5])\nplt.ylim([-0.5, 1.5])\nplt.axis('off')\nplt.savefig('shapes.png')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nfor shape in shapes:\n    ax.add_artist(shape)\nplt.xlim([-0.5, 1.5])\nplt.ylim([-0.5, 1.5])\nplt.axis('off')\nplt.savefig('shapes.png')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-artists-with-units":{"intro":"In this lab, you will learn how to create artists with units in Matplotlib. You will create different types of artists, such as a line, text, and patch, and add them to a plot. You will also set the units for the x and y axes, and learn how to convert units to scalars.","steps":[{"title":"Import Libraries","body":["First, you need to import the necessary libraries. You will use matplotlib.pyplot for creating the plot, numpy for generating random data, and matplotlib.collections, matplotlib.lines, matplotlib.patches, and matplotlib.text for creating different types of artists."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.collections as collections\nimport matplotlib.lines as lines\nimport matplotlib.patches as patches\nimport matplotlib.text as text"}]},{"title":"Create the Figure and Axis","body":["Next, you need to create the figure and axis objects. The figure object is the top-level container for all the plot elements, while the axis object represents the x and y axes of the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Set Units for the Axes","body":["To use units for the x and y axes, you need to set the units for each axis using the set_units method. In this example, you will use centimeters as the unit."],"code":[{"lang":"python","text":"ax.xaxis.set_units('cm')\nax.yaxis.set_units('cm')"}]},{"title":"Generate Random Data","body":["To create the line artist, you need to generate some random data. You will use numpy.random to generate 2 sets of x and y coordinates for the line."],"code":[{"lang":"python","text":"x = np.array([0, 1.5])\ny = np.array([0, 2.5])"}]},{"title":"Create a Line Artist","body":["Now, you can create the line artist using the Line2D class from matplotlib.lines. You can specify the x and y coordinates, line width, color, and axis object as arguments."],"code":[{"lang":"python","text":"line = lines.Line2D(x, y, lw=2, color='black', axes=ax)"}]},{"title":"Add the Artist to the Plot","body":["To add the line artist to the plot, you need to call the add_line method of the axis object and pass the line artist as an argument."],"code":[{"lang":"python","text":"ax.add_line(line)"}]},{"title":"Create a Text Artist","body":["Next, you will create a text artist using the Text class from matplotlib.text. You can specify the x and y coordinates, text label, horizontal and vertical alignment, and axis object as arguments."],"code":[{"lang":"python","text":"t = text.Text(3, 2.5, 'text label', ha='left', va='bottom', axes=ax)"}]},{"title":"Add the Artist to the Plot","body":["To add the text artist to the plot, you need to call the add_artist method of the axis object and pass the text artist as an argument."],"code":[{"lang":"python","text":"ax.add_artist(t)"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-data-visualization-techniques":{"intro":"Matplotlib is a powerful data visualization library in Python. It provides a variety of tools for creating a wide range of graphs, charts, and plots. One of the most powerful features of Matplotlib is its ability to scale data. This lab will introduce you to the AsinhScale, which is a transformation that allows for plotting quantities that cover a very wide dynamic range that includes both positive and negative values.","steps":[{"title":"Install Matplotlib","body":["Before starting, make sure that Matplotlib is installed. You can install it using pip command as follows:"],"code":[{"lang":"python","text":"pip install matplotlib"}]},{"title":"Import Required Libraries","body":["To use the AsinhScale, we need to import the Matplotlib library and the numpy library. Numpy is a powerful numerical computing library in Python that is often used in conjunction with Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Sample Data","body":["Before we can plot data using the AsinhScale, we need to create some sample data. We will create a simple line graph using numpy's linspace method."],"code":[{"lang":"python","text":"# Prepare sample values for variations on y=x graph:\nx = np.linspace(-3, 6, 500)"}]},{"title":"Compare 'symlog' and 'asinh' behaviour on sample y=x graph","body":["Compare \"symlog\" and \"asinh\" behaviour on sample y=x graph","We will compare the behaviour of \"symlog\" and \"asinh\" on a sample y=x graph. We will plot the same graph twice, once with \"symlog\" and once with \"asinh\"."],"code":[{"lang":"python","text":"fig1 = plt.figure()\nax0, ax1 = fig1.subplots(1, 2, sharex=True)\n\nax0.plot(x, x)\nax0.set_yscale('symlog')\nax0.grid()\nax0.set_title('symlog')\n\nax1.plot(x, x)\nax1.set_yscale('asinh')\nax1.grid()\nax1.set_title('asinh')"}]},{"title":"Compare 'asinh' graphs with different scale parameter 'linear_width'","body":["Compare \"asinh\" graphs with different scale parameter \"linear_width\"","We will now compare \"asinh\" graphs with different scale parameters \"linear_width\". We will plot three graphs with different \"linear_width\" values."],"code":[{"lang":"python","text":"fig2 = plt.figure(layout='constrained')\naxs = fig2.subplots(1, 3, sharex=True)\nfor ax, (a0, base) in zip(axs, ((0.2, 2), (1.0, 0), (5.0, 10))):\n    ax.set_title(f'linear_width={a0:.3g}')\n    ax.plot(x, x, label='y=x')\n    ax.plot(x, 10*x, label='y=10x')\n    ax.plot(x, 100*x, label='y=100x')\n    ax.set_yscale('asinh', linear_width=a0, base=base)\n    ax.grid()\n    ax.legend(loc='best', fontsize='small')"}]},{"title":"Compare 'symlog' and 'asinh' scalings on 2D Cauchy-distributed random numbers","body":["Compare \"symlog\" and \"asinh\" scalings on 2D Cauchy-distributed random numbers","Finally, we will compare \"symlog\" and \"asinh\" scalings on 2D Cauchy-distributed random numbers. We will plot the same graph twice, once with \"symlog\" and once with \"asinh\"."],"code":[{"lang":"python","text":"fig3 = plt.figure()\nax = fig3.subplots(1, 1)\nr = 3 * np.tan(np.random.uniform(-np.pi / 2.02, np.pi / 2.02,\n                                 size=(5000,)))\nth = np.random.uniform(0, 2*np.pi, size=r.shape)\n\nax.scatter(r * np.cos(th), r * np.sin(th), s=4, alpha=0.5)\nax.set_xscale('asinh')\nax.set_yscale('symlog')\nax.set_xlabel('asinh')\nax.set_ylabel('symlog')\nax.set_title('2D Cauchy random deviates')\nax.set_xlim(-50, 50)\nax.set_ylim(-50, 50)\nax.grid()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig3 = plt.figure()\nax = fig3.subplots(1, 1)\nr = 3 * np.tan(np.random.uniform(-np.pi / 2.02, np.pi / 2.02,\n                                 size=(5000,)))\nth = np.random.uniform(0, 2*np.pi, size=r.shape)\n\nax.scatter(r * np.cos(th), r * np.sin(th), s=4, alpha=0.5)\nax.set_xscale('asinh')\nax.set_yscale('symlog')\nax.set_xlabel('asinh')\nax.set_ylabel('symlog')\nax.set_title('2D Cauchy random deviates')\nax.set_xlim(-50, 50)\nax.set_ylim(-50, 50)\nax.grid()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-log-log-plots":{"intro":"In this tutorial, we will learn how to create log-log plots using Matplotlib in Python. A log-log plot is a type of graph where both the x-axis and y-axis are logarithmically scaled. This allows us to visualize data that spans several orders of magnitude in a compact and informative way.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using matplotlib.pyplot to create the plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Log-Log Plot with Adjustable Box","body":["Create a Log-Log Plot with Adjustable Box","Next, we will create a log-log plot with an adjustable box. This means that both the x-axis and y-axis will have logarithmic scales, and the aspect ratio of the plot will be equal to 1."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_xscale(\"log\")\nax.set_yscale(\"log\")\nax.set_xlim(1e1, 1e3)\nax.set_ylim(1e2, 1e3)\nax.set_aspect(1)\nax.set_title(\"Log-Log Plot with Adjustable Box\")\nplt.show()"}]},{"title":"Create a Log-Log Plot with Adjustable Datalim","body":["Create a Log-Log Plot with Adjustable Datalim","Next, we will create a log-log plot with an adjustable datalim. This means that both the x-axis and y-axis will have logarithmic scales, and the aspect ratio of the plot will be adjusted to fit the data."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_xscale(\"log\")\nax.set_yscale(\"log\")\nax.set_adjustable(\"datalim\")\nax.plot([1, 3, 10], [1, 9, 100], \"o-\")\nax.set_xlim(1e-1, 1e2)\nax.set_ylim(1e-1, 1e3)\nax.set_aspect(1)\nax.set_title(\"Log-Log Plot with Adjustable Datalim\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.set_xscale(\"log\")\nax.set_yscale(\"log\")\nax.set_adjustable(\"datalim\")\nax.plot([1, 3, 10], [1, 9, 100], \"o-\")\nax.set_xlim(1e-1, 1e2)\nax.set_ylim(1e-1, 1e3)\nax.set_aspect(1)\nax.set_title(\"Log-Log Plot with Adjustable Datalim\")\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-programmatically-controlling-subplot-adjustm":{"intro":"Matplotlib is a powerful library for creating visualizations in Python. Sometimes, when creating plots, you may need to adjust the subplot parameters manually. This lab will show you how to programmatically adjust subplot parameters based on the size of the labels.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We will need matplotlib.pyplot and matplotlib.transforms to create the plot and manipulate the subplot parameters."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.transforms as mtransforms"}]},{"title":"Create the plot","body":["Let's create a simple line plot with some long y-labels."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(range(10))\nax.set_yticks([2, 5, 7], labels=['really, really, really', 'long', 'labels'])"}]},{"title":"Define the draw callback function","body":["Define the draw callback function","We will define a function that will be called every time the plot is drawn. This function will calculate the bounding boxes of the y-labels, determine if the subplot leaves enough room for the labels, and adjust the subplot parameters if necessary."],"code":[{"lang":"python","text":"def on_draw(event):\n    bboxes = []\n    for label in ax.get_yticklabels():\n        # Bounding box in pixels\n        bbox_px = label.get_window_extent()\n        # Transform to relative figure coordinates. This is the inverse of\n        # transFigure.\n        bbox_fig = bbox_px.transformed(fig.transFigure.inverted())\n        bboxes.append(bbox_fig)\n    # the bbox that bounds all the bboxes, again in relative figure coords\n    bbox = mtransforms.Bbox.union(bboxes)\n    if fig.subplotpars.left < bbox.width:\n        # Move the subplot left edge more to the right\n        fig.subplots_adjust(left=1.1*bbox.width)  # pad a little\n        fig.canvas.draw()"}]},{"title":"Connect the draw event to the callback function","body":["Connect the draw event to the callback function","We need to connect the draw_event to our on_draw function."],"code":[{"lang":"python","text":"fig.canvas.mpl_connect('draw_event', on_draw)"}]},{"title":"Show the plot","body":["Finally, we will show the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-tick-placement-customization":{"intro":"In this lab, we will learn how to set the behavior of tick auto-placement in Matplotlib. By default, Matplotlib will choose the number of ticks and tick positions so that there is a reasonable number of ticks on the axis and they are located at 'round' numbers. However, there may be no ticks on the edges of the plot. We will learn how to switch the axes.autolimit_mode to 'round_numbers' to keep ticks at round numbers and also have ticks at the edges.","steps":[{"title":"Scatter plot without round_numbers autolimit_mode","body":["Scatter plot without round_numbers autolimit_mode","In this step, we will create a scatter plot without round_numbers autolimit_mode and observe the behavior of tick auto-placement."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nnp.random.seed(19680801)\n\nfig, ax = plt.subplots()\ndots = np.linspace(0.3, 1.2, 10)\nX, Y = np.meshgrid(dots, dots)\nx, y = X.ravel(), Y.ravel()\nax.scatter(x, y, c=x+y)\nplt.show()"}]},{"title":"Scatter plot with round_numbers autolimit_mode","body":["Scatter plot with round_numbers autolimit_mode","In this step, we will switch axes.autolimit_mode to 'round_numbers' and create a scatter plot to keep ticks at round numbers and also have ticks at the edges."],"code":[{"lang":"python","text":"plt.rcParams['axes.autolimit_mode'] = 'round_numbers'\n\nfig, ax = plt.subplots()\nax.scatter(x, y, c=x+y)\nplt.show()"}]},{"title":"Scatter plot with additional margin","body":["Scatter plot with additional margin","In this step, we will set an additional margin around the data using .Axes.set_xmargin / .Axes.set_ymargin while the round numbers autolimit_mode is still respected."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.scatter(x, y, c=x+y)\nax.set_xmargin(0.8)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.scatter(x, y, c=x+y)\nax.set_xmargin(0.8)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-text-wrapping-and-styling":{"intro":"In this lab, we will learn how to wrap text automatically in Python Matplotlib. We will also explore how to control the placement and style of text in a Matplotlib plot.","steps":[{"title":"Setting up the Environment","body":[],"code":[{"lang":"python","text":"!pip install matplotlib"}]},{"title":"Creating a Basic Plot","body":["Let's start by creating a basic plot with a text element. In your Python script, add the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfig = plt.figure()\nplt.axis([0, 10, 0, 10])\nplt.text(5, 5, \"Hello, Matplotlib!\", ha='center')\nplt.show()"}]},{"title":"Wrapping Text Automatically","body":["Now, let's explore how to wrap text automatically in Matplotlib. Replace the plt.text() line in your code with the following:","The wrap=True argument tells Matplotlib to wrap the text automatically."],"code":[{"lang":"python","text":"t = (\"This is a really long string that I'd rather have wrapped so that it \"\n     \"doesn't go outside of the figure, but if it's long enough it will go \"\n     \"off the top or bottom!\")\nplt.text(5, 5, t, ha='center', wrap=True)"}]},{"title":"Controlling Text Placement and Style","body":["Controlling Text Placement and Style","We can also control the placement and style of the text in our Matplotlib plot. Try adding the following code to your script:","This will add four text elements to our plot, each with a different color, font size, and position."],"code":[{"lang":"python","text":"plt.text(2, 8, \"Top Left\", fontsize=12, color='red')\nplt.text(8, 8, \"Top Right\", fontsize=12, color='blue')\nplt.text(2, 2, \"Bottom Left\", fontsize=12, color='green')\nplt.text(8, 2, \"Bottom Right\", fontsize=12, color='purple')"}]},{"title":"Saving the Plot","body":["Finally, let's save our plot as an image file. Add the following code to your script:","This will save our plot as a PNG image in the same directory as our script."],"code":[{"lang":"python","text":"fig.savefig(\"my_plot.png\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.savefig(\"my_plot.png\")"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-box-aspect":{"intro":"This lab will guide you through the process of creating different plots using the set_box_aspect() method in Matplotlib. This method sets the aspect ratio between axes height and width in physical units, independent of data limits. It is useful for producing square plots, independent of the data it contains, or to have a usual plot with the same axes dimensions next to an image plot with fixed (data-)aspect.","steps":[{"title":"A Square Axes, Independent of Data","body":["A Square Axes, Independent of Data","We will produce a square axes, no matter what the data limits are."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfig1, ax = plt.subplots()\n\nax.set_xlim(300, 400)\nax.set_box_aspect(1)\n\nplt.show()"}]},{"title":"Shared Square Axes","body":["We will produce shared subplots that are squared in size."],"code":[{"lang":"python","text":"fig2, (ax, ax2) = plt.subplots(ncols=2, sharey=True)\n\nax.plot([1, 5], [0, 10])\nax2.plot([100, 500], [10, 15])\n\nax.set_box_aspect(1)\nax2.set_box_aspect(1)\n\nplt.show()"}]},{"title":"Square Twin Axes","body":["We will produce a square axes, with a twin axes. The twinned axes takes over the box aspect of the parent."],"code":[{"lang":"python","text":"fig3, ax = plt.subplots()\n\nax2 = ax.twinx()\n\nax.plot([0, 10])\nax2.plot([12, 10])\n\nax.set_box_aspect(1)\n\nplt.show()"}]},{"title":"Normal Plot Next to Image","body":["When creating an image plot with fixed data aspect and the default adjustable=\"box\" next to a normal plot, the axes would be unequal in height. set_box_aspect() provides an easy solution to that by allowing to have the normal plot's axes use the images dimensions as box aspect. This example also shows that _constrained layout_ interplays nicely with a fixed box aspect."],"code":[{"lang":"python","text":"fig4, (ax, ax2) = plt.subplots(ncols=2, layout=\"constrained\")\n\nnp.random.seed(19680801)  # Fixing random state for reproducibility\nim = np.random.rand(16, 27)\nax.imshow(im)\n\nax2.plot([23, 45])\nax2.set_box_aspect(im.shape[0]/im.shape[1])\n\nplt.show()"}]},{"title":"Square Joint/Marginal Plot","body":["It may be desirable to show marginal distributions next to a plot of joint data. The following creates a square plot with the box aspect of the marginal axes being equal to the width- and height-ratios of the gridspec. This ensures that all axes align perfectly, independent on the size of the figure."],"code":[{"lang":"python","text":"fig5, axs = plt.subplots(2, 2, sharex=\"col\", sharey=\"row\",\n                         gridspec_kw=dict(height_ratios=[1, 3],\n                                          width_ratios=[3, 1]))\naxs[0, 1].set_visible(False)\naxs[0, 0].set_box_aspect(1/3)\naxs[1, 0].set_box_aspect(1)\naxs[1, 1].set_box_aspect(3/1)\n\nnp.random.seed(19680801)  # Fixing random state for reproducibility\nx, y = np.random.randn(2, 400) * [[.5], [180]]\naxs[1, 0].scatter(x, y)\naxs[0, 0].hist(x)\naxs[1, 1].hist(y, orientation=\"horizontal\")\n\nplt.show()"}]},{"title":"Box Aspect for Many Subplots","body":["It is possible to pass the box aspect to an Axes at initialization. The following creates a 2 by 3 subplot grid with all square Axes."],"code":[{"lang":"python","text":"fig7, axs = plt.subplots(2, 3, subplot_kw=dict(box_aspect=1),\n                         sharex=True, sharey=True, layout=\"constrained\")\n\nfor i, ax in enumerate(axs.flat):\n    ax.scatter(i % 3, -((i // 3) - 0.5)*200, c=[plt.cm.hsv(i / 6)], s=300)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig7, axs = plt.subplots(2, 3, subplot_kw=dict(box_aspect=1),\n                         sharex=True, sharey=True, layout=\"constrained\")\n\nfor i, ax in enumerate(axs.flat):\n    ax.scatter(i % 3, -((i // 3) - 0.5)*200, c=[plt.cm.hsv(i / 6)], s=300)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-inset-axes":{"intro":"Matplotlib is a powerful data visualization library in Python. It provides a variety of plots and charts to visualize data in a meaningful way. In this lab, we will learn how to create inset axes within the main plot axes using fig.add_axes in Matplotlib.","steps":[{"title":"Import Required Libraries","body":["We start by importing the necessary libraries, which include Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["In this step, we generate some data to use for the plot. We will create a Gaussian colored noise using NumPy's convolve function and plot it using Matplotlib."],"code":[{"lang":"python","text":"np.random.seed(19680801)\ndt = 0.001\nt = np.arange(0.0, 10.0, dt)\nr = np.exp(-t[:1000] / 0.05)\nx = np.random.randn(len(t))\ns = np.convolve(x, r)[:len(x)] * dt\n\nfig, main_ax = plt.subplots()\nmain_ax.plot(t, s)"}]},{"title":"Set Limits and Labels","body":["In this step, we set the limits and labels for the main plot axes."],"code":[{"lang":"python","text":"main_ax.set_xlim(0, 1)\nmain_ax.set_ylim(1.1 * np.min(s), 2 * np.max(s))\nmain_ax.set_xlabel('time (s)')\nmain_ax.set_ylabel('current (nA)')\nmain_ax.set_title('Gaussian colored noise')"}]},{"title":"Create Inset Axes","body":["In this step, we create two inset axes within the main plot axes using fig.add_axes. One will display a histogram of the data, and the other will display the impulse response."],"code":[{"lang":"python","text":"# Create right inset axes\nright_inset_ax = fig.add_axes([.65, .6, .2, .2], facecolor='k')\nright_inset_ax.hist(s, 400, density=True)\nright_inset_ax.set(title='Probability', xticks=[], yticks=[])\n\n# Create left inset axes\nleft_inset_ax = fig.add_axes([.2, .6, .2, .2], facecolor='k')\nleft_inset_ax.plot(t[:len(r)], r)\nleft_inset_ax.set(title='Impulse response', xlim=(0, .2), xticks=[], yticks=[])"}]},{"title":"Display the Plot","body":["In this step, we display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-visualization-control-in-python":{"intro":"Matplotlib is a data visualization library in Python that is used to create static, animated, and interactive visualizations in Python. It provides an object-oriented API for embedding plots into applications using general-purpose GUI toolkits like Tkinter, wxPython, Qt, or GTK. In this lab, we will learn how to control view limits and sticky edges in Matplotlib using Python.","steps":[{"title":"Plotting with Margins","body":["The margins() method in Matplotlib can be used to set margins in the plot instead of using set_xlim() and set_ylim() methods. In this step, we will learn how to zoom in and out of a plot using margins() method instead of set_xlim() and set_ylim() methods."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\ndef f(t):\n    return np.exp(-t) * np.cos(2*np.pi*t)\n\nt1 = np.arange(0.0, 3.0, 0.01)\n\n# create a subplot with margins\nax1 = plt.subplot(212)\nax1.margins(0.05) # default margin is 0.05, value 0 means fit\nax1.plot(t1, f(t1))\n\n# create a subplot with zoomed out margins\nax2 = plt.subplot(221)\nax2.margins(2, 2) # values >0.0 zoom out\nax2.plot(t1, f(t1))\nax2.set_title('Zoomed out')\n\n# create a subplot with zoomed in margins\nax3 = plt.subplot(222)\nax3.margins(x=0, y=-0.25) # values in (-0.5, 0.0) zooms in to center\nax3.plot(t1, f(t1))\nax3.set_title('Zoomed in')\n\nplt.show()"}]},{"title":"Sticky Edges","body":["Some plotting functions in Matplotlib make the axis limits \"sticky\" or immune to the margins() method. For instance, imshow() and pcolor() expect the user to want the limits to be tight around the pixels shown in the plot. If this behavior is not desired, you need to set use_sticky_edges to False. In this step, we will learn how to work around sticky edges in Matplotlib."],"code":[{"lang":"python","text":"# create a grid\ny, x = np.mgrid[:5, 1:6]\n\n# define polygon coordinates\npoly_coords = [\n    (0.25, 2.75), (3.25, 2.75),\n    (2.25, 0.75), (0.25, 0.75)\n]\n\n# create subplots\nfig, (ax1, ax2) = plt.subplots(ncols=2)\n\n# use sticky edges for ax1 and turn off sticky edges for ax2\nax2.use_sticky_edges = False\n\n# plot on both subplots\nfor ax, status in zip((ax1, ax2), ('Is', 'Is Not')):\n    cells = ax.pcolor(x, y, x+y, cmap='inferno', shading='auto') # sticky\n    ax.add_patch(\n        Polygon(poly_coords, color='forestgreen', alpha=0.5)\n    ) # not sticky\n    ax.margins(x=0.1, y=0.05)\n    ax.set_aspect('equal')\n    ax.set_title(f'{status} Sticky')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# create a grid\ny, x = np.mgrid[:5, 1:6]\n\n# define polygon coordinates\npoly_coords = [\n    (0.25, 2.75), (3.25, 2.75),\n    (2.25, 0.75), (0.25, 0.75)\n]\n\n# create subplots\nfig, (ax1, ax2) = plt.subplots(ncols=2)\n\n# use sticky edges for ax1 and turn off sticky edges for ax2\nax2.use_sticky_edges = False\n\n# plot on both subplots\nfor ax, status in zip((ax1, ax2), ('Is', 'Is Not')):\n    cells = ax.pcolor(x, y, x+y, cmap='inferno', shading='auto') # sticky\n    ax.add_patch(\n        Polygon(poly_coords, color='forestgreen', alpha=0.5)\n    ) # not sticky\n    ax.margins(x=0.1, y=0.05)\n    ax.set_aspect('equal')\n    ax.set_title(f'{status} Sticky')\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customize-matplotlib-axis-tick-and-grid":{"intro":"In this lab, you will learn how to customize the axis tick and grid properties in a Matplotlib plot using Python. Matplotlib is a data visualization library in Python that allows you to create a variety of charts and graphs. In this lab, we will focus on customizing the axis tick and grid properties of a line plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. We will be using Matplotlib and NumPy in this lab. NumPy is a library for the Python programming language, adding support for large, multi-dimensional arrays and matrices, along with a large collection of high-level mathematical functions to operate on these arrays."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["Next, we will create some data to plot. In this example, we will be using the sine function to generate a wave."],"code":[{"lang":"python","text":"t = np.arange(0.0, 2.0, 0.01)\ns = np.sin(2 * np.pi * t)"}]},{"title":"Create a Plot","body":["Now, we will create a plot using the data we just created."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(t, s)"}]},{"title":"Customize Axis Tick and Grid Properties","body":["Customize Axis Tick and Grid Properties","We can customize the axis tick and grid properties using the grid() and tick_params() functions. In this example, we will change the color and size of the tick labels and the width and style of the grid lines."],"code":[{"lang":"python","text":"ax.grid(True, linestyle='-.', linewidth=0.5, color='gray')\nax.tick_params(axis='both', which='both', labelsize=8, width=1, color='red')"}]},{"title":"Display the Plot","body":["Finally, we will display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-axes-zoom-effect":{"intro":"This tutorial will guide you on how to create a zoom effect using matplotlib. The zoom effect will allow you to connect and zoom in on two different axes.","steps":[{"title":"Importing Required Libraries","body":["In this step, we will import the necessary libraries required for this tutorial. We will import matplotlib, and the relevant libraries from mpl_toolkits.axes_grid1."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\n\nfrom matplotlib.transforms import (Bbox, TransformedBbox,\n                                   blended_transform_factory)\nfrom mpl_toolkits.axes_grid1.inset_locator import (BboxConnector,\n                                                   BboxConnectorPatch,\n                                                   BboxPatch)"}]},{"title":"Defining the Connection Between the Axes","body":["Defining the Connection Between the Axes","In this step, we will define the connection between the two axes. This function takes in two axes as inputs, as well as the minimum and maximum values for the x-axis. It then creates a bounding box and connects the two axes."],"code":[{"lang":"python","text":"def zoom_effect01(ax1, ax2, xmin, xmax, **kwargs):\n    bbox = Bbox.from_extents(xmin, 0, xmax, 1)\n\n    mybbox1 = TransformedBbox(bbox, ax1.get_xaxis_transform())\n    mybbox2 = TransformedBbox(bbox, ax2.get_xaxis_transform())\n\n    prop_patches = {**kwargs, \"ec\": \"none\", \"alpha\": 0.2}\n\n    c1, c2, bbox_patch1, bbox_patch2, p = connect_bbox(\n        mybbox1, mybbox2,\n        loc1a=3, loc2a=2, loc1b=4, loc2b=1,\n        prop_lines=kwargs, prop_patches=prop_patches)\n\n    ax1.add_patch(bbox_patch1)\n    ax2.add_patch(bbox_patch2)\n    ax2.add_patch(c1)\n    ax2.add_patch(c2)\n    ax2.add_patch(p)\n\n    return c1, c2, bbox_patch1, bbox_patch2, p"}]},{"title":"Creating the Second Zoomed Axis","body":["Creating the Second Zoomed Axis","In this step, we will create the second zoomed axis. This function takes in two axes as inputs. It then creates a bounding box for the second axis and connects it to the first axis."],"code":[{"lang":"python","text":"def zoom_effect02(ax1, ax2, **kwargs):\n    tt = ax1.transScale + (ax1.transLimits + ax2.transAxes)\n    trans = blended_transform_factory(ax2.transData, tt)\n\n    mybbox1 = ax1.bbox\n    mybbox2 = TransformedBbox(ax1.viewLim, trans)\n\n    prop_patches = {**kwargs, \"ec\": \"none\", \"alpha\": 0.2}\n\n    c1, c2, bbox_patch1, bbox_patch2, p = connect_bbox(\n        mybbox1, mybbox2,\n        loc1a=3, loc2a=2, loc1b=4, loc2b=1,\n        prop_lines=kwargs, prop_patches=prop_patches)\n\n    ax1.add_patch(bbox_patch1)\n    ax2.add_patch(bbox_patch2)\n    ax2.add_patch(c1)\n    ax2.add_patch(c2)\n    ax2.add_patch(p)\n\n    return c1, c2, bbox_patch1, bbox_patch2, p"}]},{"title":"Connecting the Axes","body":["In this step, we will connect the axes and create the zoom effect. We will create a figure with four axes and connect them using the zoom_effect01 and zoom_effect02 functions."],"code":[{"lang":"python","text":"axs = plt.figure().subplot_mosaic([\n    [\"zoom1\", \"zoom2\"],\n    [\"main\", \"main\"],\n])\n\naxs[\"main\"].set(xlim=(0, 5))\nzoom_effect01(axs[\"zoom1\"], axs[\"main\"], 0.2, 0.8)\naxs[\"zoom2\"].set(xlim=(2, 3))\nzoom_effect02(axs[\"zoom2\"], axs[\"main\"])\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"axs = plt.figure().subplot_mosaic([\n    [\"zoom1\", \"zoom2\"],\n    [\"main\", \"main\"],\n])\n\naxs[\"main\"].set(xlim=(0, 5))\nzoom_effect01(axs[\"zoom1\"], axs[\"main\"], 0.2, 0.8)\naxs[\"zoom2\"].set(xlim=(2, 3))\nzoom_effect02(axs[\"zoom2\"], axs[\"main\"])\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-horizontal-and-vertical-":{"intro":"In this tutorial, we will learn how to create lines and rectangles that span the axes in either the horizontal or vertical direction, and lines than span the axes with an arbitrary orientation using Matplotlib library in Python.","steps":[{"title":"Import Libraries","body":["Firstly, we need to import the required libraries which are Matplotlib and NumPy. NumPy is used to generate the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["We will use NumPy to generate data which we will use to plot the graph."],"code":[{"lang":"python","text":"t = np.arange(-1, 2, .01)\ns = np.sin(2 * np.pi * t)"}]},{"title":"Create a Figure and Axes","body":["We need to create a figure and axes object to plot the graph."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Plot Data","body":["Plot the data using the plot() function."],"code":[{"lang":"python","text":"ax.plot(t, s)"}]},{"title":"Add Horizontal Line","body":["Add horizontal lines using the axhline() function."],"code":[{"lang":"python","text":"# Thick red horizontal line at y=0 that spans the xrange.\nax.axhline(linewidth=8, color='#d62728')\n# Horizontal line at y=1 that spans the xrange.\nax.axhline(y=1)"}]},{"title":"Add Vertical Line","body":["Add vertical lines using the axvline() function."],"code":[{"lang":"python","text":"# Vertical line at x=1 that spans the yrange.\nax.axvline(x=1)\n# Thick blue vertical line at x=0 that spans the upper quadrant of the yrange.\nax.axvline(x=0, ymin=0.75, linewidth=8, color='#1f77b4')"}]},{"title":"Add Infinite Line","body":["Add an infinite line going through (0, 0) to (1, 1) using the axline() function."],"code":[{"lang":"python","text":"# Infinite black line going through (0, 0) to (1, 1).\nax.axline((0, 0), (1, 1), color='k')"}]},{"title":"Add Rectangle","body":["Add a rectangle using the axhspan() and axvspan() functions."],"code":[{"lang":"python","text":"# 50%-gray rectangle spanning the axes' width from y=0.25 to y=0.75.\nax.axhspan(0.25, 0.75, facecolor='0.5')\n# Green rectangle spanning the axes' height from x=1.25 to x=1.55.\nax.axvspan(1.25, 1.55, facecolor='#2ca02c')"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-axis-direction":{"intro":"Matplotlib is a popular data visualization library in Python. It provides a wide variety of options for customizing plots and charts. In this lab, we will explore how to set the axis direction in Matplotlib using the mpl_toolkits.axisartist module.","steps":[{"title":"Import Libraries","body":["Before we begin, we need to import the necessary libraries. In this lab, we will be using matplotlib.pyplot and mpl_toolkits.axisartist."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport mpl_toolkits.axisartist as axisartist"}]},{"title":"Create a Function to Set Up Axes","body":["Create a Function to Set Up Axes","We will create a function called setup_axes to set up the axes for our plots. This function takes in two parameters, a fig object and a pos object. The fig object is the figure object that we will be plotting on, and the pos object is the position of the subplot within the figure."],"code":[{"lang":"python","text":"def setup_axes(fig, pos):\n    ax = fig.add_subplot(pos, axes_class=axisartist.Axes)\n\n    ax.set_ylim(-0.1, 1.5)\n    ax.set_yticks([0, 1])\n\n    ax.axis[:].set_visible(False)\n\n    ax.axis[\"x\"] = ax.new_floating_axis(1, 0.5)\n    ax.axis[\"x\"].set_axisline_style(\"->\", size=1.5)\n\n    return ax"}]},{"title":"Set Up Axis Direction","body":["We will now create a figure object and set up the axis direction for our plots. We will create five different subplots to demonstrate different axis directions."],"code":[{"lang":"python","text":"plt.rcParams.update({\n    \"axes.titlesize\": \"medium\",\n    \"axes.titley\": 1.1,\n})\n\nfig = plt.figure(figsize=(10, 4))\nfig.subplots_adjust(bottom=0.1, top=0.9, left=0.05, right=0.95)\n\nax1 = setup_axes(fig, 251)\nax1.axis[\"x\"].set_axis_direction(\"left\")\n\nax2 = setup_axes(fig, 252)\nax2.axis[\"x\"].label.set_text(\"Label\")\nax2.axis[\"x\"].toggle(ticklabels=False)\nax2.axis[\"x\"].set_axislabel_direction(\"+\")\nax2.set_title(\"label direction=$+$\")\n\nax3 = setup_axes(fig, 253)\nax3.axis[\"x\"].label.set_text(\"Label\")\nax3.axis[\"x\"].toggle(ticklabels=False)\nax3.axis[\"x\"].set_axislabel_direction(\"-\")\nax3.set_title(\"label direction=$-$\")\n\nax4 = setup_axes(fig, 254)\nax4.axis[\"x\"].set_ticklabel_direction(\"+\")\nax4.set_title(\"ticklabel direction=$+$\")\n\nax5 = setup_axes(fig, 255)\nax5.axis[\"x\"].set_ticklabel_direction(\"-\")\nax5.set_title(\"ticklabel direction=$-$\")\n\nax7 = setup_axes(fig, 257)\nax7.axis[\"x\"].label.set_text(\"rotation=10\")\nax7.axis[\"x\"].label.set_rotation(10)\nax7.axis[\"x\"].toggle(ticklabels=False)\n\nax8 = setup_axes(fig, 258)\nax8.axis[\"x\"].set_axislabel_direction(\"-\")\nax8.axis[\"x\"].label.set_text(\"rotation=10\")\nax8.axis[\"x\"].label.set_rotation(10)\nax8.axis[\"x\"].toggle(ticklabels=False)\n\nplt.show()"}]},{"title":"Interpretation of Results","body":["The code will produce a figure with five subplots that demonstrate different axis directions. The following is a summary of the subplots:","• Subplot 1: The axis direction is set to left. • Subplot 2: The axis label direction is set to positive. • Subplot 3: The axis label direction is set to negative. • Subplot 4: The tick label direction is set to positive. • Subplot 5: The tick label direction is set to negative."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-equal-axis-aspect-ratio":{"intro":"In data visualization, it is important to present information in an accurate and visually appealing way. One way to achieve this is by setting equal axis aspect ratios in plots. This ensures that the x and y axes are scaled equally, resulting in a proportional representation of the data. In this tutorial, we will learn how to set and adjust plots with equal axis aspect ratios using Python's Matplotlib library.","steps":[{"title":"Import necessary libraries","body":["We will begin by importing the necessary libraries for this tutorial. We will be using the Matplotlib library to create plots and the NumPy library to generate data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Plot a circle with unequal axis aspect ratio","body":["Plot a circle with unequal axis aspect ratio","We will first plot a circle with unequal axis aspect ratio to demonstrate the importance of setting equal axis aspect ratios.","The resulting plot will show a circle that appears elongated due to the unequal axis aspect ratio."],"code":[{"lang":"python","text":"an = np.linspace(0, 2 * np.pi, 100)\nfig, axs = plt.subplots(2, 2)\n\naxs[0, 0].plot(3 * np.cos(an), 3 * np.sin(an))\naxs[0, 0].set_title('not equal, looks like ellipse', fontsize=10)"}]},{"title":"Plot a circle with equal axis aspect ratio","body":["Plot a circle with equal axis aspect ratio","To set the equal axis aspect ratio, we can use the axis('equal') function.","The resulting plot will show a circle that is proportional and visually appealing."],"code":[{"lang":"python","text":"axs[0, 1].plot(3 * np.cos(an), 3 * np.sin(an))\naxs[0, 1].axis('equal')\naxs[0, 1].set_title('equal, looks like circle', fontsize=10)"}]},{"title":"Adjust plot limits while maintaining equal axis aspect ratio","body":["Adjust plot limits while maintaining equal axis aspect ratio","We can also adjust the plot limits while maintaining the equal axis aspect ratio.","The resulting plot will show a circle that is still proportional even after we change the limits."],"code":[{"lang":"python","text":"axs[1, 0].plot(3 * np.cos(an), 3 * np.sin(an))\naxs[1, 0].axis('equal')\naxs[1, 0].set(xlim=(-3, 3), ylim=(-3, 3))\naxs[1, 0].set_title('still a circle, even after changing limits', fontsize=10)"}]},{"title":"Auto-adjust data limits for equal axis aspect ratio","body":["Auto-adjust data limits for equal axis aspect ratio","We can also use the set_aspect('equal', 'box') function to auto-adjust the data limits for equal axis aspect ratio.","The resulting plot will show a circle that is still proportional and visually appealing."],"code":[{"lang":"python","text":"axs[1, 1].plot(3 * np.cos(an), 3 * np.sin(an))\naxs[1, 1].set_aspect('equal', 'box')\naxs[1, 1].set_title('still a circle, auto-adjusted data limits', fontsize=10)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"axs[1, 1].plot(3 * np.cos(an), 3 * np.sin(an))\naxs[1, 1].set_aspect('equal', 'box')\naxs[1, 1].set_title('still a circle, auto-adjusted data limits', fontsize=10)"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"}};
